4在线音乐/DialogMaps/在线音乐我的界面.dsl.dsl_text:
// requirement_ids: REQ_OM_0423_01, REQ_OM_04231_01, REQ_OM_04231_02, REQ_OM_04231_03, REQ_OM_04231_04, REQ_OM_04231_05, REQ_OM_04231_06
// 我的界面 DialogMap — 覆盖我的收藏、播放历史、个人中心
DialogMap 在线音乐我的界面 {

  Entry 我的入口 ;

  // 我的界面 — 包含三个快捷入口
  // REQ_OM_0423_01
  Page 我的界面 {
    widgets: [
      { widget_id: "WDG_001" type: "button" name: "我的收藏入口" action: "进入我的收藏界面" action_type: "navigate" target: "收藏界面" condition: "" },
      { widget_id: "WDG_002" type: "button" name: "播放历史入口" action: "进入播放历史界面" action_type: "navigate" target: "播放历史界面" condition: "" },
      { widget_id: "WDG_003" type: "button" name: "个人中心入口" action: "进入账号界面" action_type: "navigate" target: "账号界面" condition: "" }
    ]
  };

  // 收藏界面 — 展示收藏歌曲、专辑、歌单、自建歌单
  // REQ_OM_04231_01, REQ_OM_04231_02
  Page 收藏界面 {
    widgets: [
      { widget_id: "WDG_010" type: "label" name: "收藏歌曲列表" action: "展示收藏状态歌名歌手名" action_type: "execute" target: null condition: "" },
      { widget_id: "WDG_011" type: "button" name: "播放全部" action: "播放全部收藏歌曲" action_type: "execute" target: null condition: "" },
      { widget_id: "WDG_012" type: "button" name: "取消收藏" action: "点击全部取消收藏进行二次确认" action_type: "execute" target: null condition: "" },
      { widget_id: "WDG_013" type: "label" name: "收藏专辑列表" action: "展示收藏状态专辑名称和封面" action_type: "execute" target: null condition: "" },
      { widget_id: "WDG_014" type: "button" name: "专辑详情" action: "展示专辑列表" action_type: "navigate" target: "专辑列表界面" condition: "" },
      { widget_id: "WDG_015" type: "label" name: "收藏歌单列表" action: "展示收藏状态和歌单名" action_type: "execute" target: null condition: "" },
      { widget_id: "WDG_016" type: "button" name: "歌单详情" action: "展示歌单列表" action_type: "navigate" target: "歌单列表界面" condition: "" },
      { widget_id: "WDG_017" type: "button" name: "自建歌单" action: "显示自建歌单列表" action_type: "navigate" target: "自建歌单界面" condition: "" }
    ]
  };

  // 专辑列表界面
  // REQ_OM_04231_03
  Page 专辑列表界面 {
    widgets: [
      { widget_id: "WDG_020" type: "label" name: "专辑歌曲列表" action: "展示专辑歌曲列表" action_type: "execute" target: null condition: "" }
    ]
  };

  // 歌单列表界面
  // REQ_OM_04231_04
  Page 歌单列表界面 {
    widgets: [
      { widget_id: "WDG_030" type: "label" name: "歌单歌曲列表" action: "展示歌单歌曲列表" action_type: "execute" target: null condition: "" }
    ]
  };

  // 自建歌单界面
  // REQ_OM_04231_05
  Page 自建歌单界面 {
    widgets: [
      { widget_id: "WDG_040" type: "label" name: "自建歌单封面" action: "展示歌单封面" action_type: "execute" target: null condition: "" },
      { widget_id: "WDG_041" type: "label" name: "自建歌单名称" action: "展示歌单名称" action_type: "execute" target: null condition: "" },
      { widget_id: "WDG_042" type: "label" name: "自建歌单歌曲列表" action: "展示歌单歌曲列表" action_type: "execute" target: null condition: "" }
    ]
  };

  // 播放历史界面
  // REQ_OM_04232_01
  Page 播放历史界面 {
    widgets: [
      { widget_id: "WDG_050" type: "label" name: "播放历史列表" action: "倒序展示本地播放历史记录歌名歌手名" action_type: "execute" target: null condition: "" }
    ]
  };

  // 账号界面
  // REQ_OM_04233_01, REQ_OM_04233_02, REQ_OM_04233_03, REQ_OM_04233_06
  Page 账号界面 {
    widgets: [
      { widget_id: "WDG_060" type: "label" name: "头像" action: "展示用户头像" action_type: "execute" target: null condition: "" },
      { widget_id: "WDG_061" type: "label" name: "昵称" action: "展示用户昵称" action_type: "execute" target: null condition: "" },
      { widget_id: "WDG_062" type: "button" name: "开通VIP按钮" action: "展示二维码进入会员购买页面" action_type: "popup" target: "会员购买界面" condition: "账号为非会员或过期会员" },
      { widget_id: "WDG_063" type: "button" name: "续费按钮" action: "展示二维码进入会员续费页面" action_type: "popup" target: "会员购买界面" condition: "账号为会员" },
      { widget_id: "WDG_064" type: "button" name: "退出登录按钮" action: "回到登录界面" action_type: "navigate" target: "二维码登录界面" condition: "" }
    ]
  };

  // 会员购买界面
  // REQ_OM_04233_04
  Page 会员购买界面 {
    widgets: [
      { widget_id: "WDG_070" type: "label" name: "会员二维码" action: "展示微信扫码二维码" action_type: "execute" target: null condition: "" },
      { widget_id: "WDG_071" type: "label" name: "扫码提示" action: "请用微信扫码进入会员购买页面" action_type: "execute" target: null condition: "" }
    ]
  };

  // 二维码登录界面 — 退出登录后回到此处
  Page 二维码登录界面 {
    widgets: [
      { widget_id: "WDG_080" type: "label" name: "登录二维码" action: "展示扫码登录二维码" action_type: "execute" target: null condition: "" },
      { widget_id: "WDG_081" type: "label" name: "扫码提示文字" action: "提示用户使用QQ、微信或QQ音乐扫码登录" action_type: "execute" target: null condition: "" }
    ]
  };

  // ===== 跳转关系 =====
  Transition 进入我的界面 {
    trigger: "WDG_ENTRY"
    trigger_type: "auto"
    from: 我的入口
    to: 我的界面
    condition: ""
    data_carried: []
  };

  Transition 进入收藏 {
    trigger: "WDG_001"
    trigger_type: "click"
    from: 我的界面
    to: 收藏界面
    condition: ""
    data_carried: []
  };

  Transition 进入播放历史 {
    trigger: "WDG_002"
    trigger_type: "click"
    from: 我的界面
    to: 播放历史界面
    condition: ""
    data_carried: []
  };

  Transition 进入账号 {
    trigger: "WDG_003"
    trigger_type: "click"
    from: 我的界面
    to: 账号界面
    condition: ""
    data_carried: []
  };

  Transition 进入专辑列表 {
    trigger: "WDG_014"
    trigger_type: "click"
    from: 收藏界面
    to: 专辑列表界面
    condition: ""
    data_carried: []
  };

  Transition 进入歌单列表 {
    trigger: "WDG_016"
    trigger_type: "click"
    from: 收藏界面
    to: 歌单列表界面
    condition: ""
    data_carried: []
  };

  Transition 进入自建歌单 {
    trigger: "WDG_017"
    trigger_type: "click"
    from: 收藏界面
    to: 自建歌单界面
    condition: ""
    data_carried: []
  };

  Transition 弹出会员购买 {
    trigger: "WDG_062"
    trigger_type: "click"
    from: 账号界面
    to: 会员购买界面
    condition: "账号为非会员或过期会员"
    data_carried: []
  };

  Transition 退出登录 {
    trigger: "WDG_064"
    trigger_type: "click"
    from: 账号界面
    to: 二维码登录界面
    condition: ""
    data_carried: []
  };
}

4在线音乐/DialogMaps/在线音乐推荐界面.dsl.dsl_text:
// requirement_ids: REQ_OM_0422_01, REQ_OM_04221_01, REQ_OM_04221_02, REQ_OM_04221_03, REQ_OM_04221_04, REQ_OM_04221_05
// 推荐界面 DialogMap — 覆盖推荐页签、歌单详情、排行榜详情
DialogMap 在线音乐推荐界面 {

  Entry 推荐入口 ;

  // QQ音乐主界面 — 四个页签入口
  // REQ_OM_0422_01
  Page QQ音乐主界面 {
    widgets: [
      { widget_id: "WDG_001" type: "button" name: "推荐页签" action: "切换到推荐界面" action_type: "navigate" target: "推荐界面" condition: "" },
      { widget_id: "WDG_002" type: "button" name: "歌手页签" action: "切换到歌手界面" action_type: "navigate" target: "歌手界面" condition: "" },
      { widget_id: "WDG_003" type: "button" name: "分类页签" action: "切换到分类界面" action_type: "navigate" target: "分类界面" condition: "" },
      { widget_id: "WDG_004" type: "button" name: "我的页签" action: "切换到我的界面" action_type: "navigate" target: "我的界面" condition: "" }
    ]
  };

  // 推荐界面 — 展示Banner、歌单推荐、排行榜
  // REQ_OM_04221_01, REQ_OM_04221_02
  Page 推荐界面 {
    widgets: [
      { widget_id: "WDG_010" type: "label" name: "Banner运营位" action: "展示运营内容" action_type: "execute" target: null condition: "" },
      { widget_id: "WDG_011" type: "button" name: "歌单入口" action: "进入歌单详情界面" action_type: "navigate" target: "歌单详情界面" condition: "" },
      { widget_id: "WDG_012" type: "button" name: "排行榜入口" action: "进入排行榜详情界面" action_type: "navigate" target: "排行榜详情界面" condition: "" },
      { widget_id: "WDG_013" type: "button" name: "排行榜播放按钮" action: "播放排行榜第一首歌" action_type: "execute" target: null condition: "" }
    ]
  };

  // 歌单详情界面
  // REQ_OM_04221_03
  Page 歌单详情界面 {
    widgets: [
      { widget_id: "WDG_020" type: "label" name: "歌单名称" action: "展示歌单名称" action_type: "execute" target: null condition: "" },
      { widget_id: "WDG_021" type: "label" name: "歌单封面" action: "展示歌单封面" action_type: "execute" target: null condition: "" },
      { widget_id: "WDG_022" type: "label" name: "歌曲列表" action: "展示歌名和歌手" action_type: "execute" target: null condition: "" },
      { widget_id: "WDG_023" type: "button" name: "添加歌单按钮" action: "添加至我喜欢的收藏" action_type: "execute" target: null condition: "" }
    ]
  };

  // 排行榜详情界面
  // REQ_OM_04221_05
  Page 排行榜详情界面 {
    widgets: [
      { widget_id: "WDG_030" type: "label" name: "排行榜名称" action: "展示排行榜名称" action_type: "execute" target: null condition: "" },
      { widget_id: "WDG_031" type: "label" name: "排行榜封面" action: "展示排行榜封面" action_type: "execute" target: null condition: "" },
      { widget_id: "WDG_032" type: "label" name: "歌曲列表" action: "展示歌曲名和歌手名" action_type: "execute" target: null condition: "" },
      { widget_id: "WDG_033" type: "label" name: "前三名标识" action: "排名前三名做特殊处理" action_type: "execute" target: null condition: "" }
    ]
  };

  // ===== 跳转关系 =====
  Transition 进入QQ音乐主界面 {
    trigger: "WDG_ENTRY"
    trigger_type: "auto"
    from: 推荐入口
    to: QQ音乐主界面
    condition: ""
    data_carried: []
  };

  Transition 切换到推荐 {
    trigger: "WDG_001"
    trigger_type: "click"
    from: QQ音乐主界面
    to: 推荐界面
    condition: ""
    data_carried: []
  };

  Transition 进入歌单详情 {
    trigger: "WDG_011"
    trigger_type: "click"
    from: 推荐界面
    to: 歌单详情界面
    condition: ""
    data_carried: []
  };

  Transition 进入排行榜详情 {
    trigger: "WDG_012"
    trigger_type: "click"
    from: 推荐界面
    to: 排行榜详情界面
    condition: ""
    data_carried: []
  };
}

4在线音乐/DialogMaps/在线音乐歌手分类界面.dsl.dsl_text:
// requirement_ids: REQ_OM_04222_01, REQ_OM_04222_02, REQ_OM_04222_03, REQ_OM_04223_01
// 歌手和分类界面 DialogMap
DialogMap 在线音乐歌手分类界面 {

  Entry 主界面入口 ;

  // QQ音乐主界面 — 四个页签入口
  Page QQ音乐主界面 {
    widgets: [
      { widget_id: "WDG_001" type: "button" name: "推荐页签" action: "切换到推荐界面" action_type: "navigate" target: "推荐界面" condition: "" },
      { widget_id: "WDG_002" type: "button" name: "歌手页签" action: "切换到歌手界面" action_type: "navigate" target: "歌手界面" condition: "" },
      { widget_id: "WDG_003" type: "button" name: "分类页签" action: "切换到分类界面" action_type: "navigate" target: "分类界面" condition: "" },
      { widget_id: "WDG_004" type: "button" name: "我的页签" action: "切换到我的界面" action_type: "navigate" target: "我的界面" condition: "" }
    ]
  };

  // 歌手界面 — 展示歌手列表，支持筛选
  // REQ_OM_04222_01, REQ_OM_04222_03
  Page 歌手界面 {
    widgets: [
      { widget_id: "WDG_010" type: "button" name: "地区筛选" action: "按地区筛选歌手" action_type: "execute" target: null condition: "" },
      { widget_id: "WDG_011" type: "button" name: "流派筛选" action: "按流派筛选歌手" action_type: "execute" target: null condition: "" },
      { widget_id: "WDG_012" type: "button" name: "字母A-Z筛选" action: "按字母快速筛选歌手" action_type: "execute" target: null condition: "" },
      { widget_id: "WDG_013" type: "button" name: "歌手卡片" action: "进入歌手列表详情页" action_type: "navigate" target: "歌手列表详情界面" condition: "" }
    ]
  };

  // 歌手列表详情界面
  // REQ_OM_04222_03
  Page 歌手列表详情界面 {
    widgets: [
      { widget_id: "WDG_020" type: "label" name: "歌手名称" action: "展示歌手名称" action_type: "execute" target: null condition: "" },
      { widget_id: "WDG_021" type: "label" name: "歌手歌曲列表" action: "展示歌手对应歌曲列表" action_type: "execute" target: null condition: "" }
    ]
  };

  // 分类界面 — 展示全部分类
  // REQ_OM_04223_01
  Page 分类界面 {
    widgets: [
      { widget_id: "WDG_030" type: "button" name: "全部分类" action: "展示所有分类内容" action_type: "execute" target: null condition: "" }
    ]
  };

  // ===== 跳转关系 =====
  Transition 进入主界面 {
    trigger: "WDG_ENTRY"
    trigger_type: "auto"
    from: 主界面入口
    to: QQ音乐主界面
    condition: ""
    data_carried: []
  };

  Transition 切换到歌手 {
    trigger: "WDG_002"
    trigger_type: "click"
    from: QQ音乐主界面
    to: 歌手界面
    condition: ""
    data_carried: []
  };

  Transition 切换到分类 {
    trigger: "WDG_003"
    trigger_type: "click"
    from: QQ音乐主界面
    to: 分类界面
    condition: ""
    data_carried: []
  };

  Transition 进入歌手详情 {
    trigger: "WDG_013"
    trigger_type: "click"
    from: 歌手界面
    to: 歌手列表详情界面
    condition: ""
    data_carried: []
  };
}

4在线音乐/DialogMaps/在线音乐正在播放界面.dsl.dsl_text:
// requirement_ids: REQ_OM_0424_01, REQ_OM_0424_02, REQ_OM_0424_03, REQ_OM_0424_04, REQ_OM_0424_05, REQ_OM_0424_06
// 正在播放界面 DialogMap — 覆盖播放控制、音质选择、播放列表
DialogMap 在线音乐正在播放界面 {

  Entry 播放入口 ;

  // 正在播放界面
  // REQ_OM_0424_01, REQ_OM_0424_02, REQ_OM_0424_03
  Page 正在播放界面 {
    widgets: [
      { widget_id: "WDG_001" type: "label" name: "歌曲封面" action: "展示歌曲封面" action_type: "execute" target: null condition: "" },
      { widget_id: "WDG_002" type: "label" name: "歌名" action: "展示歌名" action_type: "execute" target: null condition: "" },
      { widget_id: "WDG_003" type: "label" name: "歌手" action: "展示歌手名" action_type: "execute" target: null condition: "" },
      { widget_id: "WDG_004" type: "label" name: "歌词" action: "展示歌词" action_type: "execute" target: null condition: "" },
      { widget_id: "WDG_005" type: "label" name: "播放进度条" action: "展示播放进度条" action_type: "execute" target: null condition: "" },
      { widget_id: "WDG_006" type: "label" name: "歌曲时长" action: "展示歌曲时长" action_type: "execute" target: null condition: "" },
      { widget_id: "WDG_007" type: "label" name: "歌曲属性标识" action: "根据歌曲属性展示试听VIP付费等标识" action_type: "execute" target: null condition: "" },
      { widget_id: "WDG_008" type: "button" name: "播放模式按钮" action: "切换播放模式" action_type: "execute" target: null condition: "" },
