      { widget_id: "WDG_010" type: "button" name: "下一首按钮" action: "切换到下一首" action_type: "execute" target: null condition: "" },
      { widget_id: "WDG_011" type: "button" name: "暂停播放按钮" action: "切换暂停和播放状态" action_type: "execute" target: null condition: "" },
      { widget_id: "WDG_012" type: "button" name: "收藏按钮" action: "收藏当前歌曲" action_type: "execute" target: null condition: "" },
      { widget_id: "WDG_013" type: "button" name: "播放列表按钮" action: "出现播放列表弹窗" action_type: "popup" target: "播放列表弹窗" condition: "" },
      { widget_id: "WDG_014" type: "button" name: "音质选择按钮" action: "选择标准高品无损音质" action_type: "execute" target: null condition: "" }
    ]
  };

  // 播放列表弹窗
  // REQ_OM_0424_06
  Page 播放列表弹窗 {
    widgets: [
      { widget_id: "WDG_020" type: "label" name: "播放列表" action: "展示歌名歌手当前正在播放歌曲高亮" action_type: "execute" target: null condition: "" }
    ]
  };

  // 底部播放器 — 缩小播放界面入口
  // REQ_OM_0424_04
  Page 底部播放器 {
    widgets: [
      { widget_id: "WDG_030" type: "label" name: "歌曲封面" action: "展示歌曲封面" action_type: "execute" target: null condition: "" },
      { widget_id: "WDG_031" type: "label" name: "歌名" action: "展示歌名" action_type: "execute" target: null condition: "" },
      { widget_id: "WDG_032" type: "button" name: "收藏按钮" action: "收藏当前歌曲" action_type: "execute" target: null condition: "" },
      { widget_id: "WDG_033" type: "button" name: "播放模式按钮" action: "切换播放模式" action_type: "execute" target: null condition: "" },
      { widget_id: "WDG_034" type: "button" name: "播放列表按钮" action: "出现播放列表弹窗" action_type: "popup" target: "播放列表弹窗" condition: "" },
      { widget_id: "WDG_035" type: "button" name: "上一首按钮" action: "切换到上一首" action_type: "execute" target: null condition: "" },
      { widget_id: "WDG_036" type: "button" name: "下一首按钮" action: "切换到下一首" action_type: "execute" target: null condition: "" },
      { widget_id: "WDG_037" type: "button" name: "暂停播放按钮" action: "切换暂停和播放状态" action_type: "execute" target: null condition: "" }
    ]
  };

  // ===== 跳转关系 =====
  Transition 进入正在播放界面 {
    trigger: "WDG_ENTRY"
    trigger_type: "auto"
    from: 播放入口
    to: 正在播放界面
    condition: ""
    data_carried: []
  };

  Transition 弹出播放列表 {
    trigger: "WDG_013"
    trigger_type: "click"
    from: 正在播放界面
    to: 播放列表弹窗
    condition: ""
    data_carried: []
  };

  Transition 切换到底部播放器 {
    trigger: "WDG_001"
    trigger_type: "auto"
    from: 正在播放界面
    to: 底部播放器
    condition: "用户切换到其他界面"
    data_carried: []
  };
}

4在线音乐/DialogMaps/在线音乐登录流程.dsl.dsl_text:
// requirement_ids: REQ_OM_0421_03, REQ_OM_04211_01, REQ_OM_04212_01, REQ_OM_04212_02, REQ_OM_04212_03
// 登录流程 DialogMap — 覆盖游客模式、二维码登录、登录成功/过期
DialogMap 在线音乐登录流程 {

  Entry 音乐入口 ;

  // 游客模式界面 — 未登录时展示
  // REQ_OM_0421_03
  Page 游客模式界面 {
    widgets: [
      { widget_id: "WDG_001" type: "button" name: "登录按钮" action: "进入二维码登录界面" action_type: "navigate" target: "二维码登录界面" condition: "" }
    ]
  };

  // 二维码登录界面 — 展示二维码和提示文字
  // REQ_OM_04211_01
  Page 二维码登录界面 {
    widgets: [
      { widget_id: "WDG_010" type: "label" name: "登录二维码" action: "展示扫码登录二维码" action_type: "execute" target: null condition: "" },
      { widget_id: "WDG_011" type: "label" name: "扫码提示文字" action: "提示用户使用QQ、微信或QQ音乐扫码登录" action_type: "execute" target: null condition: "" }
    ]
  };

  // QQ音乐主界面 — 登录成功后进入
  // REQ_OM_04212_01
  Page QQ音乐主界面 {
    widgets: [
      { widget_id: "WDG_020" type: "tab" name: "推荐页签" action: "切换到推荐界面" action_type: "execute" target: null condition: "" },
      { widget_id: "WDG_021" type: "tab" name: "歌手页签" action: "切换到歌手界面" action_type: "execute" target: null condition: "" },
      { widget_id: "WDG_022" type: "tab" name: "分类页签" action: "切换到分类界面" action_type: "execute" target: null condition: "" },
      { widget_id: "WDG_023" type: "tab" name: "我的页签" action: "切换到我的界面" action_type: "execute" target: null condition: "" }
    ]
  };

  // ===== 跳转关系 =====
  Transition 进入游客模式 {
    trigger: "WDG_ENTRY"
    trigger_type: "auto"
    from: 音乐入口
    to: 游客模式界面
    condition: ""
    data_carried: []
  };

  Transition 进入二维码登录 {
    trigger: "WDG_001"
    trigger_type: "click"
    from: 游客模式界面
    to: 二维码登录界面
    condition: ""
    data_carried: []
  };

  Transition 扫码登录成功 {
    trigger: "WDG_010"
    trigger_type: "auto"
    from: 二维码登录界面
    to: QQ音乐主界面
    condition: "用户扫码成功"
    data_carried: []
  };
}

4在线音乐/Environment.dsl.dsl_text:
// requirement_ids: REQ_OM_0421_01, REQ_OM_0421_02, REQ_OM_0421_03, REQ_OM_0422_01, REQ_OM_0423_01
// ====== 环境定义 ======
// 在线音乐模块运行在 ICC（智能座舱控制器）上，ICC 为系统承载者
Environment {
  // === 建模对象（系统本身）===
  // REQ_OM_0401_01: 在线音乐功能模块
  Machine 在线音乐模块;

  // === 外部设备 ===
  // REQ_OM_0421_01, REQ_OM_0421_02: 语音识别系统提供播放歌曲意图输入
  Device 语音识别系统;
  // REQ_OM_0421_03 ~ REQ_OM_0424_06: 用户通过 ICC 上的界面进行操作
  Device ICC_QQ音乐界面;
  Device ICC_推荐界面;
  Device ICC_歌手界面;
  Device ICC_分类界面;
  Device ICC_我的界面;
  Device ICC_歌单详情界面;
  Device ICC_排行榜详情界面;
  Device ICC_歌手列表详情界面;
  Device ICC_收藏界面;
  Device ICC_播放历史界面;
  Device ICC_账号界面;
  Device ICC_正在播放界面;
  Device ICC_播放列表弹窗;
  Device ICC_二维码登录界面;
  Device ICC_游客模式界面;
  Device ICC_会员购买界面;

  // === 人类参与者 ===
  Human 用户;

  // === 连接定义 ===

  // REQ_OM_0421_01, REQ_OM_0421_02: 用户语音输入 → 语音识别系统 → 在线音乐模块搜索
  Connect from 用户 to 语音识别系统 {
    Interaction 语音输入播放歌曲 { Event 用户语音输入播放歌曲 };
  };
  Connect from 语音识别系统 to 在线音乐模块 {
    Interaction 播放歌曲意图 { Event 语音识别出播放歌曲意图 };
  };

  // REQ_OM_0421_02: 在线音乐模块响应搜索
  Connect from 在线音乐模块 to 语音识别系统 {
    Interaction 搜索结果返回 { Event 在线音乐模块返回搜索结果 };
  };

  // REQ_OM_0421_03: 用户点击进入音乐，展示游客模式
  Connect from 用户 to ICC_游客模式界面 {
    Interaction 进入音乐入口 { Event 用户点击进入音乐 };
  };
  Connect from 在线音乐模块 to ICC_游客模式界面 {
    Interaction 展示游客模式 { Event 系统展示游客模式 };
  };

  // REQ_OM_04211_01: 二维码登录界面展示
  Connect from 在线音乐模块 to ICC_二维码登录界面 {
    Interaction 展示登录二维码 { Event 系统展示二维码和扫码提示文字 };
  };

  // 游客模式 → 二维码登录界面
  Connect from ICC_游客模式界面 to ICC_二维码登录界面 {
    Interaction 游客转登录 { Event 用户在游客模式下点击登录 };
  };

  // REQ_OM_04212_01 ~ REQ_OM_04212_03: 登录有效期与过期处理
  Connect from 在线音乐模块 to ICC_QQ音乐界面 {
    Interaction 登录成功展示主界面 { Event 系统登录成功后进入QQ音乐界面 };
    Interaction 定时刷新登录状态 { Event 系统定时刷新登录有效期 };
    Interaction 登录过期退出 { Event 系统因登录过期退出登录 };
  };

  // REQ_OM_0422_01: QQ音乐界面展示四个页签
  Connect from ICC_QQ音乐界面 to ICC_推荐界面 {
    Interaction 展示推荐页签 { Event 系统展示推荐界面 };
  };
  Connect from ICC_QQ音乐界面 to ICC_歌手界面 {
    Interaction 展示歌手页签 { Event 系统展示歌手界面 };
  };
  Connect from ICC_QQ音乐界面 to ICC_分类界面 {
    Interaction 展示分类页签 { Event 系统展示分类界面 };
  };
  Connect from ICC_QQ音乐界面 to ICC_我的界面 {
    Interaction 展示我的页签 { Event 系统展示我的界面 };
  };

  // REQ_OM_04221_01 ~ REQ_OM_04221_05: 推荐界面相关交互
  Connect from 在线音乐模块 to ICC_推荐界面 {
    Interaction 展示Banner运营位 { Event 系统展示Banner运营位 };
    Interaction 展示歌单推荐 { Event 系统展示歌单推荐 };
    Interaction 展示排行榜 { Event 系统展示排行榜 };
  };
  Connect from ICC_推荐界面 to ICC_歌单详情界面 {
    Interaction 进入歌单详情 { Event 用户点击歌单进入详情 };
  };
  Connect from 在线音乐模块 to ICC_歌单详情界面 {
    Interaction 展示歌单详情 { Event 系统展示歌单名称封面歌名歌手和添加按钮 };
    Interaction 歌单加载提示 { Event 系统展示加载提示或到底啦提示 };
    Interaction 添加歌单至收藏 { Event 用户点击添加歌单按钮添加至收藏 };
  };
  Connect from ICC_推荐界面 to ICC_排行榜详情界面 {
    Interaction 进入排行榜详情 { Event 用户点击排行榜进入详情 };
  };
  Connect from 在线音乐模块 to ICC_排行榜详情界面 {
    Interaction 展示排行榜详情 { Event 系统展示排行榜名称封面歌曲歌手前三名特殊处理 };
    Interaction 排行榜加载提示 { Event 系统展示加载提示或到底啦提示 };
  };
  Connect from ICC_推荐界面 to 在线音乐模块 {
    Interaction 播放排行第一首 { Event 用户点击排行榜播放按钮播放第一首歌 };
  };

  // REQ_OM_04222_01 ~ REQ_OM_04222_03: 歌手界面相关
  Connect from 在线音乐模块 to ICC_歌手界面 {
    Interaction 展示歌手列表 { Event 系统展示歌手图片和名称支持筛选 };
  };
  Connect from ICC_歌手界面 to ICC_歌手列表详情界面 {
    Interaction 进入歌手详情 { Event 用户点击歌手进入列表详情页 };
  };

  // REQ_OM_04223_01: 分类界面
  Connect from 在线音乐模块 to ICC_分类界面 {
    Interaction 展示分类列表 { Event 系统展示全部分类内容 };
  };

  // REQ_OM_0423_01, REQ_OM_04231_01 ~ REQ_OM_04231_06: 我的界面与收藏
  Connect from ICC_我的界面 to ICC_收藏界面 {
    Interaction 进入收藏界面 { Event 用户进入我的收藏界面 };
  };
  Connect from 在线音乐模块 to ICC_收藏界面 {
    Interaction 展示收藏内容 { Event 系统展示收藏歌曲专辑歌单和自建歌单 };
    Interaction 同步收藏内容 { Event 系统开机同步APP端收藏内容 };
    Interaction 收藏同步失败提示 { Event 系统三次同步失败后提示用户 };
  };
  Connect from ICC_收藏界面 to 在线音乐模块 {
    Interaction 播放收藏歌曲 { Event 用户点击收藏歌曲开始播放 };
    Interaction 取消收藏确认 { Event 用户点击全部取消收藏进行二次确认 };
    Interaction 取消收藏单曲 { Event 用户取消收藏单曲只更新状态不刷新列表 };
    Interaction 播放专辑列表 { Event 用户点击收藏专辑展示专辑列表并播放 };
    Interaction 播放歌单列表 { Event 用户点击收藏歌单展示歌单列表并播放 };
    Interaction 播放自建歌单 { Event 用户点击自建歌单显示歌单列表并播放 };
  };

  // REQ_OM_04232_01: 播放历史
  Connect from ICC_我的界面 to ICC_播放历史界面 {
    Interaction 进入播放历史 { Event 用户进入播放历史界面 };
  };
  Connect from 在线音乐模块 to ICC_播放历史界面 {
    Interaction 展示播放历史 { Event 系统倒序展示本地播放历史记录 };
  };
  Connect from ICC_播放历史界面 to 在线音乐模块 {
    Interaction 播放历史歌曲 { Event 用户点击播放历史歌曲开始播放并插入列表首位 };
  };

  // REQ_OM_04233_01 ~ REQ_OM_04233_06: 账号管理
  Connect from ICC_我的界面 to ICC_账号界面 {
    Interaction 进入账号界面 { Event 用户进入个人中心 };
  };
  Connect from 在线音乐模块 to ICC_账号界面 {
    Interaction 展示非会员信息 { Event 系统展示非会员账号信息 };
    Interaction 展示会员信息 { Event 系统展示会员账号信息 };
    Interaction 展示过期会员信息 { Event 系统展示过期会员账号信息 };
    Interaction 同步VIP状态 { Event 系统同步VIP状态 };
  };
  Connect from ICC_账号界面 to ICC_会员购买界面 {
    Interaction 进入会员购买 { Event 用户点击开通或续费会员展示二维码 };
  };
  Connect from ICC_账号界面 to ICC_二维码登录界面 {
    Interaction 退出登录 { Event 用户点击退出登录回到登录界面 };
  };

  // REQ_OM_0424_01 ~ REQ_OM_0424_06: 正在播放界面
  Connect from ICC_QQ音乐界面 to ICC_正在播放界面 {
    Interaction 进入正在播放界面 { Event 用户点击左下角播放界面入口 };
  };
  Connect from 在线音乐模块 to ICC_正在播放界面 {
    Interaction 展示正在播放内容 { Event 系统展示封面歌名歌手歌词进度条等控件 };
    Interaction 展示歌曲属性标识 { Event 系统根据歌曲属性展示试听VIP付费标识 };
    Interaction 展示底部播放器 { Event 系统展示底部缩小播放器入口和歌曲封面 };
    Interaction 提供音质选择 { Event 系统提供标准高品无损音质选择 };
  };
  Connect from ICC_正在播放界面 to ICC_播放列表弹窗 {
    Interaction 展示播放列表 { Event 用户点击播放列表按钮出现播放列表 };
  };
  Connect from 在线音乐模块 to ICC_播放列表弹窗 {
    Interaction 展示播放列表内容 { Event 系统展示播放列表歌名歌手当前歌曲高亮 };
  };

  // REQ_OM_0425_01 ~ REQ_OM_0425_03: 无法播放提醒
  Connect from 在线音乐模块 to ICC_正在播放界面 {
    Interaction 试听片段提醒 { Event 系统toast提示正在播放试听片段 };
    Interaction 播放异常切换 { Event 系统自动切换下一首并toast提示 };
    Interaction VIP音质提醒 { Event 系统toast提示开通会员后畅享音质 };
  };
}

4在线音乐/ExternalScenarios/切换界面展示底部播放器.dsl.dsl_text:
// requirement_ids: REQ_OM_0424_04
// 场景：用户切换到其他界面时，左下角展示缩小播放界面入口
