4在线音乐/Statecharts/QQ音乐页签状态机.dsl.dsl_text:
// requirement_ids: REQ_OM_0422_01, REQ_OM_04221_01, REQ_OM_04222_01, REQ_OM_04223_01, REQ_OM_0423_01
// QQ音乐页签状态机 — 管理当前显示的页签界面
Statechart QQ音乐页签状态机 {

  // ===== Start 节点（必需）=====
  Start 进入QQ音乐 ;

  // ===== 状态定义 =====
  // 推荐界面，默认页签，展示Banner、歌单推荐和排行榜
  // REQ_OM_0422_01, REQ_OM_04221_01
  State 推荐界面 {
    during_actions: [
      {pre_think: 0 post_think: 0 express: "当前页签 = 推荐" type: "action"}
    ]
  };

  // 歌手界面，支持按地区、流派、字母筛选
  // REQ_OM_04222_01
  State 歌手界面 {
    during_actions: [
      {pre_think: 0 post_think: 0 express: "当前页签 = 歌手" type: "action"}
    ]
  };

  // 分类界面，展示全部分类内容
  // REQ_OM_04223_01
  State 分类界面 {
    during_actions: [
      {pre_think: 0 post_think: 0 express: "当前页签 = 分类" type: "action"}
    ]
  };

  // 我的界面，包含我的收藏、播放历史、个人中心
  // REQ_OM_0423_01
  State 我的界面 {
    during_actions: [
      {pre_think: 0 post_think: 0 express: "当前页签 = 我的" type: "action"}
    ]
  };

  // ===== 转换定义 =====
  // 登录后默认进入推荐界面
  // REQ_OM_0422_01
  Transition 默认进入推荐 {
    condition: "登录成功"
    from: 进入QQ音乐
    to: 推荐界面
  };

  // 页签切换
  Transition 切换到歌手 {
    condition: "用户点击歌手页签"
    from: 推荐界面
    to: 歌手界面
  };
  Transition 切换到分类 {
    condition: "用户点击分类页签"
    from: 推荐界面
    to: 分类界面
  };
  Transition 切换到我的 {
    condition: "用户点击我的页签"
    from: 推荐界面
    to: 我的界面
  };

  Transition 从歌手到推荐 {
    condition: "用户点击推荐页签"
    from: 歌手界面
    to: 推荐界面
  };
  Transition 从歌手到分类 {
    condition: "用户点击分类页签"
    from: 歌手界面
    to: 分类界面
  };
  Transition 从歌手到我的 {
    condition: "用户点击我的页签"
    from: 歌手界面
    to: 我的界面
  };

  Transition 从分类到推荐 {
    condition: "用户点击推荐页签"
    from: 分类界面
    to: 推荐界面
  };
  Transition 从分类到歌手 {
    condition: "用户点击歌手页签"
    from: 分类界面
    to: 歌手界面
  };
  Transition 从分类到我的 {
    condition: "用户点击我的页签"
    from: 分类界面
    to: 我的界面
  };

  Transition 从我的到推荐 {
    condition: "用户点击推荐页签"
    from: 我的界面
    to: 推荐界面
  };
  Transition 从我的到歌手 {
    condition: "用户点击歌手页签"
    from: 我的界面
    to: 歌手界面
  };
  Transition 从我的到分类 {
    condition: "用户点击分类页签"
    from: 我的界面
    to: 分类界面
  };
}

4在线音乐/Statecharts/会员状态机.dsl.dsl_text:
// requirement_ids: REQ_OM_04233_01, REQ_OM_04233_02, REQ_OM_04233_03, REQ_OM_04233_04, REQ_OM_04233_05
// 会员状态状态机 — 管理账号会员状态
Statechart 会员状态机 {

  // ===== Start 节点（必需）=====
  Start 账号初始化 ;

  // ===== 状态定义 =====
  // 非会员账号，展示头像、昵称、开通VIP按钮、退出登录按钮
  // REQ_OM_04233_01
  State 非会员 {
    during_actions: [
      {pre_think: 0 post_think: 0 express: "账号状态 = 非会员" type: "action"}
    ]
  };

  // 会员账号，展示头像、昵称、VIP标识、续费按钮、退出登录按钮
  // REQ_OM_04233_02
  State 会员 {
    during_actions: [
      {pre_think: 0 post_think: 0 express: "账号状态 = 会员" type: "action"}
    ]
  };

  // 过期会员账号，展示头像、昵称、灰显VIP标识、开通VIP按钮、退出登录按钮
  // REQ_OM_04233_03
  State 过期会员 {
    during_actions: [
      {pre_think: 0 post_think: 0 express: "账号状态 = 过期会员" type: "action"}
    ]
  };

  // ===== 转换定义 =====
  // 新账号初始为非会员
  Transition 初始为非会员 {
    condition: "系统初始化"
    from: 账号初始化
    to: 非会员
  };

  // 非会员开通VIP后变为会员
  // REQ_OM_04233_04, REQ_OM_04233_05
  Transition 非会员开通VIP {
    condition: "支付开通完成"
    from: 非会员
    to: 会员
  };

  // 会员续费后保持会员状态
  // REQ_OM_04233_04, REQ_OM_04233_05
  Transition 会员续费 {
    condition: "支付续费完成"
    from: 会员
    to: 会员
  };

  // 会员过期后变为过期会员
  Transition 会员到期 {
    condition: "会员有效期过期"
    from: 会员
    to: 过期会员
  };

  // 过期会员重新开通后变为会员
  // REQ_OM_04233_04
  Transition 过期会员重新开通 {
    condition: "支付开通完成"
    from: 过期会员
    to: 会员
  };
}

4在线音乐/Statecharts/播放状态机.dsl.dsl_text:
// requirement_ids: REQ_OM_0424_03
// 播放状态状态机 — 管理音乐播放状态
Statechart 播放状态机 {

  // ===== Start 节点（必需）=====
  Start 播放初始化 ;

  // ===== 状态定义 =====
  // 播放中状态
  State 播放中 {
    during_actions: [
      {pre_think: 0 post_think: 0 express: "播放状态 = 播放中" type: "action"}
    ]
  };

  // 暂停状态
  State 暂停 {
    during_actions: [
      {pre_think: 0 post_think: 0 express: "播放状态 = 暂停" type: "action"}
    ]
  };

  // 未播放状态（初始）
  State 未播放 {
    during_actions: [
      {pre_think: 0 post_think: 0 express: "播放状态 = 未播放" type: "action"}
    ]
  };

  // ===== 转换定义 =====
  Transition 初始未播放 {
    condition: "系统初始化"
    from: 播放初始化
    to: 未播放
  };

  // 开始播放
  Transition 开始播放 {
    condition: "用户点击播放按钮"
    from: 未播放
    to: 播放中
  };

  Transition 继续播放 {
    condition: "用户点击播放按钮"
    from: 暂停
    to: 播放中
  };

  // 暂停播放
  Transition 暂停播放 {
    condition: "用户点击暂停按钮"
    from: 播放中
    to: 暂停
  };

  // 播放异常自动切换下一首
  // REQ_OM_0425_02
  Transition 播放异常切换 {
    condition: "播放异常如歌曲版权变更"
    from: 播放中
    to: 播放中
  };

  // 下一首
  Transition 切换到下一首 {
    condition: "用户点击下一首按钮"
    from: 播放中
    to: 播放中
  };

  // 上一首
  Transition 切换到上一首 {
    condition: "用户点击上一首按钮"
    from: 播放中
    to: 播放中
  };
}

4在线音乐/Statecharts/收藏同步状态机.dsl.dsl_text:
// requirement_ids: REQ_OM_04231_06
// 收藏同步状态机 — 管理开机收藏同步流程
Statechart 收藏同步状态机 {

  // ===== Start 节点（必需）=====
  Start 开机启动 ;

  // ===== 状态定义 =====
  // 同步等待中
  State 等待同步 {
    during_actions: [
      {pre_think: 0 post_think: 0 express: "同步状态 = 等待中" type: "action"}
    ]
  };

  // 同步成功
  State 同步成功 {
    during_actions: [
      {pre_think: 0 post_think: 0 express: "同步状态 = 成功" type: "action"}
    ]
  };

  // 同步重试中（最多三次）
  State 同步重试中 {
    during_actions: [
      {pre_think: 0 post_think: 0 express: "同步状态 = 重试中" type: "action"}
    ]
  };

  // 同步失败（三次后提示用户）
  State 同步失败 {
    during_actions: [
      {pre_think: 0 post_think: 0 express: "同步状态 = 失败" type: "action"}
    ]
  };

  // ===== 转换定义 =====
  Transition 开机进入同步 {
    condition: "每次开机"
    from: 开机启动
    to: 等待同步
  };

  Transition 同步成功 {
    condition: "同步APP端收藏内容成功"
    from: 等待同步
    to: 同步成功
  };

  Transition 同步失败进入重试 {
    condition: "同步失败且重试次数小于3"
    from: 等待同步
    to: 同步重试中
  };

  Transition 重试成功 {
    condition: "重试同步成功"
    from: 同步重试中
    to: 同步成功
  };

  Transition 重试继续 {
    condition: "重试失败且重试次数小于3"
    from: 同步重试中
    to: 同步重试中
  };

  Transition 三次失败后提示 {
    condition: "三次同步均失败"
    from: 同步重试中
    to: 同步失败
  };
}

4在线音乐/Statecharts/登录状态机.dsl.dsl_text:
// requirement_ids: REQ_OM_0421_03, REQ_OM_04212_01, REQ_OM_04212_02, REQ_OM_04212_03, REQ_OM_04233_06
// 登录状态状态机 — 管理用户登录状态的转换
Statechart 登录状态机 {

  // ===== Start 节点（必需）=====
  Start 系统启动 ;

  // ===== 状态定义 =====
  // 未登录状态，初始状态，展示游客模式
  // REQ_OM_0421_03: 未登录QQ音乐时，展示游客模式
  State 未登录 {
    during_actions: [
      {pre_think: 0 post_think: 0 express: "登录状态 = 游客模式" type: "action"}
    ]
  };

  // 已登录状态，进入QQ音乐主界面
  // REQ_OM_04212_01: 登录后定时刷新登录有效期
  State 已登录 {
    during_actions: [
      {pre_think: 0 post_think: 0 express: "登录状态 = 已登录" type: "action"},
      {pre_think: 0 post_think: 0 express: "定时刷新登录有效期" type: "action"}
    ]
  };

  // ===== 转换定义 =====
  // 系统启动后默认进入未登录状态
  Transition 启动进入未登录 {
    condition: "系统初始化"
    from: 系统启动
    to: 未登录
  };

  // 扫码登录成功后进入已登录状态
  // REQ_OM_04212_01
  Transition 扫码登录成功 {
    condition: "用户扫码登录成功"
    from: 未登录
    to: 已登录
  };

  // 登录过期后退出到未登录状态
  // REQ_OM_04212_02, REQ_OM_04212_03
  Transition 登录过期退出 {
    condition: "登录有效期过期"
    from: 已登录
    to: 未登录
  };

  // 用户主动退出登录
  // REQ_OM_04233_06
  Transition 用户主动退出 {
    condition: "用户点击退出登录"
    from: 已登录
    to: 未登录
  };
}

5在线电台/DialogMaps/在线电台界面.dialogmap.dsl.dsl_text:
// DialogMap: 在线电台界面
// Covers: REQ-ONLINE-RADIO-001 ~ REQ-ONLINE-RADIO-031
// run_id: RUN-ONLINE-RADIO-20260726-001

DialogMap 在线电台界面 {
    Entry 入口;

    // === 页面定义 ===

    // REQ-ONLINE-RADIO-001: 主页/分类频道/广播/我的 导航入口
    Page 在线电台主页 {
        widgets: [
            { widget_id: "tab_home" type: "tab" name: "主页" action: "switch_tab" action_type: "click" target: "主页页面" }
            { widget_id: "tab_category" type: "tab" name: "分类频道" action: "switch_tab" action_type: "click" target: "分类频道页" }
            { widget_id: "tab_radio" type: "tab" name: "广播" action: "switch_tab" action_type: "click" target: "广播页" }
            { widget_id: "tab_mine" type: "tab" name: "我的" action: "switch_tab" action_type: "click" target: "我的页面" }
        ]
    };

    // REQ-ONLINE-RADIO-002,003,004,005,006: 主页内容
    Page 主页页面 {
        widgets: [
            { widget_id: "banner" type: "image_carousel" name: "Banner运营位" action: "display" action_type: "none" target: null }
            { widget_id: "recommend_playlist" type: "card_list" name: "推荐播单" action: "navigate" action_type: "click" target: "专辑详情页"
              display_variants: [
                  { variant_id: "click_cover" display_text: "点击封面跳转专辑列表/详情页" condition: "true" }
                  { variant_id: "click_play_button" display_text: "点击播放按钮直接播放" condition: "true" }
              ]
            }
            { widget_id: "ranking" type: "card_list" name: "排行榜" action: "expand" action_type: "click" target: "排行榜展开页"
              display_variants: [
                  { variant_id: "collapsed" display_text: "首次进入展示一行" condition: "首次进入" }
                  { variant_id: "expanded" display_text: "点击展示更多类型" condition: "用户点击排行榜" }
              ]
            }
            { widget_id: "guess_you_like" type: "card" name: "猜你喜欢" action: "navigate" action_type: "click" target: "猜你喜欢详情页" }
        ]
    };

    // REQ-ONLINE-RADIO-006: 猜你喜欢详情页
    Page 猜你喜欢详情页 {
        widgets: [
            { widget_id: "cover_image" type: "image" name: "封面" action: "display" action_type: "none" target: null }
            { widget_id: "play_count" type: "label" name: "播放数量" action: "display" action_type: "none" target: null }
            { widget_id: "radio_name" type: "label" name: "电台名称" action: "display" action_type: "none" target: null }
            { widget_id: "anchor_name" type: "label" name: "主播名称" action: "display" action_type: "none" target: null }
            { widget_id: "subscribe_status" type: "button" name: "订阅状态" action: "toggle" action_type: "click" target: null }
            { widget_id: "episode_list" type: "list" name: "每一期声音列表" action: "navigate" action_type: "click" target: "每一期详情"
              display_variants: [
                  { variant_id: "episode_name" display_text: "展示声音名称" condition: "true" }
                  { variant_id: "episode_duration" display_text: "展示时长" condition: "true" }
              ]
            }
        ]
    };

    // REQ-ONLINE-RADIO-007,008,009: 分类频道
    Page 分类频道页 {
        widgets: [
            { widget_id: "category_list" type: "list" name: "分类列表" action: "navigate" action_type: "click" target: "分类详情页"
              display_variants: [
                  { variant_id: "visible_categories" display_text: "显示相声评书/有声书/音乐/儿童/娱乐/VIP等" condition: "正常显示" }
                  { variant_id: "all_categories" display_text: "滑到底展示所有分类名称" condition: "滑到底部" }
              ]
            }
        ]
    };

    // 分类详情页
    Page 分类详情页 {
        widgets: [
            { widget_id: "content_item" type: "card" name: "分类内容项" action: "play" action_type: "click" target: "播放界面"
              display_variants: [
                  { variant_id: "item_cover" display_text: "封面" condition: "true" }
                  { variant_id: "item_name" display_text: "名称" condition: "true" }
                  { variant_id: "item_status" display_text: "播放状态" condition: "true" }
              ]
            }
        ]
    };

    // REQ-ONLINE-RADIO-010,011,012: 广播页
    Page 广播页 {
        widgets: [
            { widget_id: "featured" type: "label" name: "精选" action: "display" action_type: "none" target: null }
            { widget_id: "region_tab" type: "tab_group" name: "地区页签" action: "filter" action_type: "click" target: "地区电台列表"
              display_variants: [
                  { variant_id: "all_regions" display_text: "按省份显示所有地区标签" condition: "全部地区" }
                  { variant_id: "local_station" display_text: "默认展示本地台" condition: "默认" }
                  { variant_id: "region_collapsed" display_text: "部分折叠" condition: "UIUE需求" }
              ]
            }
            { widget_id: "category_tab" type: "tab_group" name: "分类页签" action: "filter" action_type: "click" target: "分类电台列表"
              display_variants: [
                  { variant_id: "all_categories" display_text: "按节目内容分类显示" condition: "全部分类" }
                  { variant_id: "category_collapsed" display_text: "部分折叠" condition: "UIUE需求" }
              ]
            }
            { widget_id: "station_cover" type: "image" name: "电台封面" action: "navigate" action_type: "click" target: "电台详情页" }
        ]
    };

    // 电台详情页
    Page 电台详情页 {};

    // REQ-ONLINE-RADIO-013,014,015,016,030,031: 播放界面
    Page 播放界面 {
        widgets: [
            { widget_id: "cover" type: "image" name: "封面" action: "display" action_type: "none" target: null }
            { widget_id: "title" type: "label" name: "名称" action: "display" action_type: "none" target: null }
            { widget_id: "source" type: "label" name: "来源" action: "display" action_type: "none" target: null }
            { widget_id: "description" type: "label" name: "简介与正文内容" action: "display" action_type: "none" target: null }
            { widget_id: "progress_bar" type: "slider" name: "进度条" action: "seek" action_type: "drag" target: null }
            { widget_id: "duration" type: "label" name: "时长" action: "display" action_type: "none" target: null }
            { widget_id: "current_progress" type: "label" name: "当前进度" action: "display" action_type: "none" target: null }
            { widget_id: "prev_button" type: "button" name: "上一首" action: "prev" action_type: "click" target: null }
            { widget_id: "next_button" type: "button" name: "下一首" action: "next" action_type: "click" target: null }
            { widget_id: "play_pause_button" type: "button" name: "播放/暂停" action: "toggle_play" action_type: "click" target: null }
            { widget_id: "playlist_button" type: "button" name: "播放列表" action: "show_playlist" action_type: "click" target: "播放列表弹窗" }
        ]
    };

    // 播放列表弹窗
    Page 播放列表弹窗 {
        widgets: [
            { widget_id: "episode_list" type: "list" name: "期列表" action: "select" action_type: "click" target: null
              display_variants: [
                  { variant_id: "episode_name" display_text: "每一期名称" condition: "true" }
                  { variant_id: "current_highlight" display_text: "当前播放内容高亮" condition: "当前播放" }
              ]
            }
        ]
    };

    // REQ-ONLINE-RADIO-017,018,019,020,021,022,023,024,025,026,027,028,029: 我的页面
    Page 我的页面 {
        widgets: [
            { widget_id: "subscription" type: "tab" name: "订阅" action: "switch_tab" action_type: "click" target: "订阅页面" }
            { widget_id: "history" type: "tab" name: "历史" action: "switch_tab" action_type: "click" target: "历史页面" }
            { widget_id: "purchased" type: "tab" name: "已购" action: "switch_tab" action_type: "click" target: "已购页面" }
            { widget_id: "account" type: "tab" name: "账户信息" action: "switch_tab" action_type: "click" target: "账户页面" }
        ]
    };

    Page 订阅页面 {
        widgets: [
            { widget_id: "login_prompt" type: "label" name: "请先登录" action: "display" action_type: "none" target: null
              condition: "登录状态信号 == 未登录" }
            { widget_id: "empty_prompt" type: "label" name: "还没有订阅内容" action: "display" action_type: "none" target: null
              condition: "登录状态信号 == 已登录 and 订阅内容数 == 0" }
            { widget_id: "subscription_list" type: "list" name: "订阅内容列表" action: "display" action_type: "none" target: null
              condition: "登录状态信号 == 已登录 and 订阅内容数 > 0" }
        ]
    };

    Page 历史页面 {
        widgets: [
            { widget_id: "history_list" type: "list" name: "播放历史" action: "display" action_type: "none" target: null
              display_variants: [
                  { variant_id: "cover_and_name" display_text: "每个电台展示封面和名称" condition: "true" }
                  { variant_id: "time_desc" display_text: "以播放时间倒序排列" condition: "true" }
              ]
            }
        ]
    };

    Page 已购页面 {
        widgets: [
            { widget_id: "login_prompt" type: "label" name: "请先登录" action: "display" action_type: "none" target: null
              condition: "登录状态信号 == 未登录" }
            { widget_id: "empty_prompt" type: "label" name: "还没有购买专辑" action: "display" action_type: "none" target: null
              condition: "登录状态信号 == 已登录 and 已购内容数 == 0" }
            { widget_id: "purchased_list" type: "list" name: "已购内容列表" action: "display" action_type: "none" target: null
              condition: "登录状态信号 == 已登录 and 已购内容数 > 0" }
        ]
    };

    Page 账户页面 {
        widgets: [
            { widget_id: "avatar" type: "image" name: "头像" action: "display" action_type: "none" target: null }
            { widget_id: "nickname" type: "label" name: "昵称" action: "display" action_type: "none" target: null }
            { widget_id: "vip_button" type: "button" name: "开通VIP" action: "navigate" action_type: "click" target: null
              condition: "VIP会员状态信号 == 非会员" }
            { widget_id: "vip_icon_active" type: "icon" name: "亮显VIP图标" action: "display" action_type: "none" target: null
              condition: "VIP会员状态信号 == 会员" }
            { widget_id: "vip_icon_grey" type: "icon" name: "灰显VIP图标" action: "display" action_type: "none" target: null
              condition: "VIP会员状态信号 == 过期会员" }
        ]
    };

    // === 页面跳转 Transition ===

    Transition 启动进入 {
        trigger: "进入在线电台"
        trigger_type: "user_action"
        from: 入口
        to: 在线电台主页
    };

    Transition 切换到主页 {
        trigger: "点击主页Tab"
        trigger_type: "click"
        from: 在线电台主页
        to: 主页页面
    };

    Transition 切换到分类频道 {
        trigger: "点击分类频道Tab"
        trigger_type: "click"
        from: 在线电台主页
        to: 分类频道页
    };

    Transition 切换到广播 {
        trigger: "点击广播Tab"
        trigger_type: "click"
        from: 在线电台主页
        to: 广播页
    };

    Transition 切换到我的 {
        trigger: "点击我的Tab"
        trigger_type: "click"
        from: 在线电台主页
        to: 我的页面
    };

    Transition 点击分类名称 {
        trigger: "点击分类名称"
        trigger_type: "click"
        from: 分类频道页
        to: 分类详情页
    };

    Transition 点击节目播放 {
        trigger: "点击节目"
        trigger_type: "click"
        from: 分类详情页
        to: 播放界面
    };

    Transition 点击电台封面 {
        trigger: "点击电台封面"
        trigger_type: "click"
        from: 广播页
        to: 播放界面
    };

    Transition 点击播放列表 {
        trigger: "点击播放列表按钮"
        trigger_type: "click"
        from: 播放界面
        to: 播放列表弹窗
    };
}

5在线电台/Environment.dsl.dsl_text:
// Environment DSL for 在线电台
// run_id: RUN-ONLINE-RADIO-20260726-001
// feature_id: FEATURE-ONLINE-RADIO
// Generated in local-fallback mode

Environment {
    // --- Components ---

    // REQ-ONLINE-RADIO-001~031: 在线电台模块 (Machine)
    Machine 在线电台模块;

    // External data source: 大数据/数据接口
    Controller 大数据接口;

    // External data source: APP返回数据
    Controller APP数据接口;

    // External auth service
    Controller 登录认证服务;

    // External VIP service
    Controller VIP会员服务;

    // Device
    Device 中控屏;

    // Human user
    Human 用户;

    // --- Connectors and Interactions ---

    // 用户 ↔ 中控屏
    Connect from 用户 to 中控屏 {
        // REQ-ONLINE-RADIO-001: 进入在线电台
        Interaction 进入在线电台 { Event 用户点击在线电台入口 };
        // REQ-ONLINE-RADIO-004: 点击推荐播单封面
        Interaction 点击推荐播单封面 { Event 用户点击推荐播单封面 };
        // REQ-ONLINE-RADIO-004: 点击封面播放按钮
        Interaction 点击封面播放按钮 { Event 用户点击封面播放按钮 };
        // REQ-ONLINE-RADIO-005: 点击排行榜区域
        Interaction 点击排行榜区域 { Event 用户点击排行榜区域 };
        // REQ-ONLINE-RADIO-006: 点击猜你喜欢
        Interaction 点击猜你喜欢 { Event 用户点击猜你喜欢 };
        // REQ-ONLINE-RADIO-008: 点击分类名称
        Interaction 点击分类名称 { Event 用户点击分类名称 };
        // REQ-ONLINE-RADIO-009: 点击某一节目
        Interaction 点击某一节目 { Event 用户点击某一节目 };
        // REQ-ONLINE-RADIO-011: 选择地区页签
        Interaction 选择地区页签 { Event 用户选择地区页签 };
        // REQ-ONLINE-RADIO-012: 选择分类页签
        Interaction 选择分类页签 { Event 用户选择分类页签 };
        // REQ-ONLINE-RADIO-014: 点击播放列表按钮
        Interaction 点击播放列表按钮 { Event 用户点击播放列表按钮 };
        // REQ-ONLINE-RADIO-013: 播放控制
        Interaction 点击播放暂停 { Event 用户点击播放暂停 };
        Interaction 点击上一首 { Event 用户点击上一首 };
        Interaction 点击下一首 { Event 用户点击下一首 };
        // Navigate to tabs
        Interaction 进入主页 { Event 用户点击主页 };
        Interaction 进入分类频道 { Event 用户点击分类频道 };
        Interaction 进入广播 { Event 用户点击广播 };
        Interaction 进入我的 { Event 用户点击我的 };
    };

    // 中控屏 ↔ 在线电台模块 (UI events processed)
    Connect from 中控屏 to 在线电台模块 {
        // REQ-ONLINE-RADIO-001: 展示导航入口
        Interaction 展示导航入口 { Signal 显示主页_分类频道_广播_我的 };
        // REQ-ONLINE-RADIO-002: 主页展示模块
        Interaction 展示主页模块 { Signal 显示Banner_推荐播单_排行榜_猜你喜欢 };
        // REQ-ONLINE-RADIO-003: 展示Banner
        Interaction 展示Banner { Signal 显示Banner三张图 };
        // REQ-ONLINE-RADIO-007: 展示分类
        Interaction 展示分类 { Signal 显示各分类名称 };
        // REQ-ONLINE-RADIO-010: 展示广播精选
        Interaction 展示广播精选 { Signal 显示广播精选 };
        // REQ-ONLINE-RADIO-013: 展示播放界面
        Interaction 展示播放界面 { Signal 显示播放控件 };
        // REQ-ONLINE-RADIO-017: 展示我的页面
        Interaction 展示我的页面 { Signal 显示订阅_历史_已购_账户 };
        // REQ-ONLINE-RADIO-030: Toast/弹框提醒
        Interaction 显示播放提醒 { Signal 显示Toast弹框 };
    };

    // 在线电台模块 ↔ 大数据接口 (data fetching)
    Connect from 在线电台模块 to 大数据接口 {
        // REQ-ONLINE-RADIO-003: 获取Banner数据
        Interaction 获取Banner数据 { Signal 请求Banner数据 };
        // REQ-ONLINE-RADIO-004: 获取推荐播单数据
        Interaction 获取推荐播单数据 { Signal 请求推荐播单数据 };
        // REQ-ONLINE-RADIO-005: 获取排行榜数据
        Interaction 获取排行榜数据 { Signal 请求排行榜数据 };
        // REQ-ONLINE-RADIO-012: 获取分类数据
        Interaction 获取分类数据 { Signal 请求分类数据 };
    };

    Connect from 大数据接口 to 在线电台模块 {
        Interaction 返回Banner数据 { Signal Banner数据 };
        Interaction 返回推荐播单数据 { Signal 推荐播单数据 };
        Interaction 返回排行榜数据 { Signal 排行榜数据 };
        Interaction 返回分类数据 { Signal 分类数据 };
    };

    // 在线电台模块 ↔ APP数据接口
    Connect from 在线电台模块 to APP数据接口 {
        Interaction 请求APP返回数据 { Signal 发送APP数据请求 };
    };

    Connect from APP数据接口 to 在线电台模块 {
        Interaction 接收APP返回数据 { Signal APP返回数据 };
    };

    // 在线电台模块 ↔ 登录认证服务
    Connect from 在线电台模块 to 登录认证服务 {
        Interaction 检查登录状态 { Signal 发送登录状态请求 };
    };

    Connect from 登录认证服务 to 在线电台模块 {
        Interaction 返回登录状态 { Signal 登录状态信号 };
    };

    // 在线电台模块 ↔ VIP会员服务
    Connect from 在线电台模块 to VIP会员服务 {
        Interaction 检查VIP状态 { Signal 发送VIP状态请求 };
    };

    Connect from VIP会员服务 to 在线电台模块 {
        Interaction 返回VIP状态 { Signal VIP会员状态信号 };
    };
}

