5在线电台/Statecharts/VIP节目播放.statechart.dsl.dsl_text:
// Statechart: VIP节目播放
// Covers: REQ-ONLINE-RADIO-015, REQ-ONLINE-RADIO-016, REQ-ONLINE-RADIO-030, REQ-ONLINE-RADIO-031
// run_id: RUN-ONLINE-RADIO-20260726-001

Statechart VIP节目播放 {
    Start 开始;

    // Login check
    Condition 检查登录 {
        condition: "登录状态信号 == 已登录"
    };

    Condition 检查VIP {
        condition: "VIP会员状态信号 == 会员"
    };

    // States
    State 未登录状态 {
        during_actions: [
            { pre_think: 0 post_think: 0 express: "提示用户登录" type: "toast" }
        ]
    };

    State 试听模式 {
        during_actions: [
            { pre_think: 0 post_think: 0 express: "正在试听" type: "toast" }
        ]
    };

    State 完整播放 {
        during_actions: [
            { pre_think: 0 post_think: 0 express: "完整播放VIP节目" type: "playback" }
        ]
    };

    State 试听结束弹框 {};

    State 播放异常 {
        during_actions: [
            { pre_think: 0 post_think: 0 express: "播放异常" type: "toast" }
        ]
    };

    // Transitions
    Transition 尝试播放VIP {
        from: 开始
        to: 检查登录
    };

    Transition 已登录 {
        condition: "登录状态信号 == 已登录"
        from: 检查登录
        to: 检查VIP
    };

    Transition 未登录 {
        condition: "登录状态信号 == 未登录"
        from: 检查登录
        to: 未登录状态
    };

    Transition 是会员 {
        condition: "VIP会员状态信号 == 会员"
        from: 检查VIP
        to: 完整播放
    };

    Transition 非会员 {
        condition: "VIP会员状态信号 == 非会员"
        from: 检查VIP
        to: 试听模式
    };

    Transition 试听结束 {
        from: 试听模式
        to: 试听结束弹框
    };

    Transition 播放出错 {
        condition: "播放状态信号 == 异常"
        from: 完整播放
        to: 播放异常
    };
}

