5在线电台/Statecharts/我的页面导航.statechart.dsl.dsl_text:
// Statechart: 我的页面导航
// Covers: REQ-ONLINE-RADIO-018, REQ-ONLINE-RADIO-019, REQ-ONLINE-RADIO-020, REQ-ONLINE-RADIO-021
// Covers: REQ-ONLINE-RADIO-022, REQ-ONLINE-RADIO-023, REQ-ONLINE-RADIO-024, REQ-ONLINE-RADIO-025
// Covers: REQ-ONLINE-RADIO-026, REQ-ONLINE-RADIO-027, REQ-ONLINE-RADIO-028, REQ-ONLINE-RADIO-029
// run_id: RUN-ONLINE-RADIO-20260726-001

Statechart 我的页面导航 {
    Start 开始;

    Condition 检查登录 {
        condition: "登录状态信号 == 已登录"
    };

    Condition 检查订阅状态 {
        condition: "有订阅内容"
    };

    Condition 检查已购状态 {
        condition: "有已购内容"
    };

    Condition 检查VIP会员 {
        condition: "VIP会员状态信号 == 会员"
    };

    State 我的主页面 {
        during_actions: [
            { pre_think: 0 post_think: 0 express: "展示订阅/历史/已购/账户入口，默认在历史" type: "display" }
        ]
    };

    State 订阅页面_未登录 {
        during_actions: [
            { pre_think: 0 post_think: 0 express: "请先登录" type: "toast" }
        ]
    };

    State 订阅页面_无内容 {
        during_actions: [
            { pre_think: 0 post_think: 0 express: "还没有订阅内容" type: "display" }
        ]
    };

    State 订阅页面_有内容 {
        during_actions: [
            { pre_think: 0 post_think: 0 express: "展示订阅内容（专辑名称，播放时间倒序）" type: "display" }
        ]
    };

    State 历史页面 {
        during_actions: [
            { pre_think: 0 post_think: 0 express: "展示播放历史（封面+名称，时间倒序）" type: "display" }
        ]
    };

    State 已购页面_未登录 {
        during_actions: [
            { pre_think: 0 post_think: 0 express: "请先登录" type: "toast" }
        ]
    };

    State 已购页面_无内容 {
        during_actions: [
            { pre_think: 0 post_think: 0 express: "还没有购买专辑" type: "display" }
        ]
    };

    State 已购页面_有内容 {
        during_actions: [
            { pre_think: 0 post_think: 0 express: "展示已购内容（专辑名称，播放时间倒序）" type: "display" }
        ]
    };

    State 账户页面_游客 {};

    State 账户页面_非会员 {
        during_actions: [
            { pre_think: 0 post_think: 0 express: "显示头像、昵称、开通VIP按钮" type: "display" }
        ]
    };

    State 账户页面_会员 {
        during_actions: [
            { pre_think: 0 post_think: 0 express: "显示头像、昵称、亮显VIP图标" type: "display" }
        ]
    };

    State 账户页面_过期会员 {
        during_actions: [
            { pre_think: 0 post_think: 0 express: "显示头像、昵称、灰显VIP图标" type: "display" }
        ]
    };

    // Transitions - 订阅
    Transition 进入我的 {
        from: 开始
        to: 我的主页面
    };

    Transition 点击订阅_未登录 {
        condition: "登录状态信号 == 未登录"
        from: 我的主页面
        to: 订阅页面_未登录
    };

    Transition 点击订阅_无内容 {
        condition: "登录状态信号 == 已登录 and 订阅内容数 == 0"
        from: 我的主页面
        to: 订阅页面_无内容
    };

    Transition 点击订阅_有内容 {
        condition: "登录状态信号 == 已登录 and 订阅内容数 > 0"
        from: 我的主页面
        to: 订阅页面_有内容
    };

    // Transitions - 已购
    Transition 点击已购_未登录 {
        condition: "登录状态信号 == 未登录"
        from: 我的主页面
        to: 已购页面_未登录
    };

    Transition 点击已购_无内容 {
        condition: "登录状态信号 == 已登录 and 已购内容数 == 0"
        from: 我的主页面
        to: 已购页面_无内容
    };

    Transition 点击已购_有内容 {
        condition: "登录状态信号 == 已登录 and 已购内容数 > 0"
        from: 我的主页面
        to: 已购页面_有内容
    };

    // Transitions - 账户
    Transition 点击账户_游客 {
        condition: "登录状态信号 == 未登录"
        from: 我的主页面
        to: 账户页面_游客
    };

    Transition 点击账户_非会员 {
        condition: "登录状态信号 == 已登录 and VIP会员状态信号 == 非会员"
        from: 我的主页面
        to: 账户页面_非会员
    };

    Transition 点击账户_会员 {
        condition: "登录状态信号 == 已登录 and VIP会员状态信号 == 会员"
        from: 我的主页面
        to: 账户页面_会员
    };

    Transition 点击账户_过期会员 {
        condition: "登录状态信号 == 已登录 and VIP会员状态信号 == 过期会员"
        from: 我的主页面
        to: 账户页面_过期会员
    };
}

