6收音机/Environment.dsl.dsl_text:
// requirement_ids: REQ_收音机_621_01, REQ_收音机_621_02, REQ_收音机_622_01, REQ_收音机_622_02, REQ_收音机_622_03, REQ_收音机_623_01, REQ_收音机_631_01, REQ_收音机_632_01, REQ_收音机_632_03, REQ_收音机_632_04, REQ_收音机_633_01
// ====== 环境定义 ======
// 收音机系统外部环境：用户通过中控屏上的收音机APP和N合1Widget与收音机硬件模块交互，
// 收音机硬件模块负责FM/AM无线信号的接收与解调
Environment {
  // === 建模对象（系统本身）===
  Machine 收音机模块;

  // === 人类参与者 ===
  Human 驾驶员;

  // === 外部设备 ===
  // [REQ_收音机_622_01, REQ_收音机_622_03] 中控屏上的收音机控制界面
  Device 中控屏_收音机控制界面;
  // [REQ_收音机_622_02, REQ_收音机_631_01] 中控屏上的N合1Widget
  Device 中控屏_N合1Widget;
  // [REQ_收音机_621_01, REQ_收音机_621_02] 提供FM/AM空中广播信号接收能力
  Device 收音机硬件模块;
  // [REQ_收音机_632_04] 语音系统提供语音指令识别
  Device 语音系统;

  // === 连接定义 ===

  // 驾驶员操作收音机控制界面
  // [REQ_收音机_622_01]
  Connect from 驾驶员 to 中控屏_收音机控制界面 {
    Interaction 点击打开收音机APP { Event 驾驶员点击打开收音机APP };
    Interaction 波段切换操作 { Event 驾驶员切换FM_AM波段 };
    Interaction 点击播放停止按键 { Event 驾驶员点击播放_停止按键 };
    Interaction 点击向前搜索 { Event 驾驶员点击向前搜索按钮 };
    Interaction 点击向后搜索 { Event 驾驶员点击向后搜索按钮 };
    Interaction 点击上一个电台 { Event 驾驶员点击上一个电台按钮 };
    Interaction 点击下一个电台 { Event 驾驶员点击下一个电台按钮 };
    Interaction 点击搜索列表电台 { Event 驾驶员点击搜索列表中的电台 };
    Interaction 点击收藏列表电台 { Event 驾驶员点击收藏列表中的电台 };
    Interaction 发起自动搜台 { Event 驾驶员发起自动搜台 };
    Interaction 点击屏幕中止搜索 { Event 驾驶员点击屏幕中止搜索 };
    Interaction 收藏当前电台 { Event 驾驶员收藏当前电台 };
    Interaction 取消收藏电台 { Event 驾驶员取消收藏电台 };
  };

  // 收音机控制界面将操作指令发送给收音机模块
  // [REQ_收音机_622_01, REQ_收音机_621_02, REQ_收音机_631_01, REQ_收音机_632_01]
  Connect from 中控屏_收音机控制界面 to 收音机模块 {
    Interaction 打开收音机指令 { Event 中控屏_收音机控制界面发送打开收音机指令 };
    Interaction 波段切换指令 { Event 中控屏_收音机控制界面发送波段切换指令 };
    Interaction 播放停止指令 { Event 中控屏_收音机控制界面发送播放_停止指令 };
    Interaction 手动搜台指令 { Event 中控屏_收音机控制界面发送手动搜台指令 };
    Interaction 自动搜台指令 { Event 中控屏_收音机控制界面发送自动搜台指令 };
    Interaction 终止搜台指令 { Event 中控屏_收音机控制界面发送终止搜台指令 };
    Interaction 列表切换电台指令 { Event 中控屏_收音机控制界面发送列表切换电台指令 };
    Interaction 上下电台切换指令 { Event 中控屏_收音机控制界面发送上下电台切换指令 };
    Interaction 收藏操作指令 { Event 中控屏_收音机控制界面发送收藏操作指令 };
  };

  // 收音机模块反馈到收音机控制界面
  // [REQ_收音机_621_02, REQ_收音机_631_01, REQ_收音机_632_05, REQ_收音机_633_03]
  Connect from 收音机模块 to 中控屏_收音机控制界面 {
    Interaction 显示电台信息 { Event 系统显示当前电台信息 };
    Interaction 显示当前频点 { Event 系统显示当前频点 };
    Interaction 更新搜索列表 { Event 系统更新搜索列表 };
    Interaction 更新收藏列表 { Event 系统更新收藏列表 };
    Interaction 显示搜索进度 { Event 系统显示搜索进度频率 };
    Interaction 高亮当前播放电台 { Event 系统高亮显示当前播放电台 };
  };

  // 收音机控制界面显示给驾驶员
  // [REQ_收音机_621_02, REQ_收音机_632_05]
  Connect from 中控屏_收音机控制界面 to 驾驶员 {
    Interaction 显示电台信息反馈 { Event 中控屏_收音机控制界面显示电台信息 };
    Interaction 显示频点反馈 { Event 中控屏_收音机控制界面显示当前频点 };
    Interaction 显示搜索列表反馈 { Event 中控屏_收音机控制界面显示搜索列表 };
    Interaction 显示收藏列表反馈 { Event 中控屏_收音机控制界面显示收藏列表 };
  };

  // 驾驶员操作N合1Widget
  // [REQ_收音机_622_02, REQ_收音机_631_01]
  Connect from 驾驶员 to 中控屏_N合1Widget {
    Interaction Widget向前搜索 { Event 驾驶员通过Widget点击向前搜索 };
    Interaction Widget向后搜索 { Event 驾驶员通过Widget点击向后搜索 };
  };

  // N合1Widget将操作指令发送给收音机模块
  // [REQ_收音机_622_02, REQ_收音机_631_01]
  Connect from 中控屏_N合1Widget to 收音机模块 {
    Interaction Widget手动搜台指令 { Event 中控屏_N合1Widget发送手动搜台指令 };
  };

  // 收音机硬件模块向收音机模块提供信号
  // [REQ_收音机_621_01, REQ_收音机_621_02]
  Connect from 收音机硬件模块 to 收音机模块 {
    Interaction 接收无线信号 { Event 收音机硬件模块接收FM_AM无线信号 };
    Interaction 信号强度反馈 { Event 收音机硬件模块反馈信号强度 };
  };

  // 收音机模块控制收音机硬件模块
  // [REQ_收音机_621_02, REQ_收音机_631_01, REQ_收音机_633_03]
  Connect from 收音机模块 to 收音机硬件模块 {
    Interaction 调谐频率指令 { Event 系统向收音机硬件模块发送调谐频率指令 };
    Interaction 波段设置指令 { Event 系统向收音机硬件模块发送波段设置指令 };
    Interaction 静音控制指令 { Event 系统向收音机硬件模块发送静音控制指令 };
  };

  // 驾驶员通过语音控制收音机
  // [REQ_收音机_632_04]
  Connect from 驾驶员 to 语音系统 {
    Interaction 语音播放停止命令 { Event 驾驶员发出语音播放_停止命令 };
    Interaction 语音上下电台命令 { Event 驾驶员发出语音上下电台命令 };
  };

  // 语音系统将指令发送给收音机模块
  // [REQ_收音机_632_04]
  Connect from 语音系统 to 收音机模块 {
    Interaction 语音播放停止指令 { Event 语音系统发送播放_停止指令 };
    Interaction 语音上下电台指令 { Event 语音系统发送上下电台切换指令 };
  };
}

6收音机/ExternalScenarios/全频段搜索不到电台时不更新列表.d.dsl_text:
// requirement_ids: REQ_收音机_633_07
Scenario 全频段搜索不到电台时不更新列表 {
    // [前置条件] 自动搜索进行中
    // --- 正文开始 ---
    Interaction 发起自动搜台;
    Interaction 自动搜台指令;
    Interaction 静音控制指令;
    while ( 全波段搜索未完成 ) {
        Interaction 调谐频率指令;
        Interaction 信号强度反馈;
    }
    Interaction 静音控制指令;
    // --- 正文结束 ---
    // [后置条件] 不更新搜索列表，回到搜索前正在播放的电台频率，根据整车tuning降低输出音量
}

