Scenario 用户点击APP图标启动收音机 {
    // [前置条件] 收音机处于关闭状态
    // --- 正文开始 ---
    Interaction 点击打开收音机APP;
    Interaction 打开收音机指令;
    if ( 有播放记录 ) {
        Interaction 显示电台信息;
        Interaction 显示电台信息反馈;
