    // [后置条件] 收音机控制界面打开，应用冷启动时长≤2s
}

6收音机/ExternalScenarios/用户点击向前搜索有效电台.dsl.dsl_text:
// requirement_ids: REQ_收音机_631_01, REQ_收音机_631_02, REQ_收音机_631_03
Scenario 用户点击向前搜索有效电台 {
    // [前置条件] 收音机处于播放或停止状态；当前处于某波段
    // --- 正文开始 ---
    Interaction 点击向前搜索;
    Interaction 手动搜台指令;
    Interaction 静音控制指令;
    Interaction 调谐频率指令;
    while ( 未找到满足信号强度的电台 ) {
        Interaction 显示搜索进度;
        Interaction 调谐频率指令;
        if ( 到达最小频点 ) {
            Interaction 调谐频率指令;
        }
    }
    Interaction 信号强度反馈;
    if ( 信号强度满足规定 ) {
        Interaction 显示当前频点;
        Interaction 显示频点反馈;
        Interaction 显示电台信息;
    }
    // --- 正文结束 ---
    // [后置条件] 播放满足信号强度的电台，搜索过程中系统静音
}

