6收音机/Statecharts/收音机列表状态机.dsl.dsl_text:
// requirement_ids: REQ_收音机_622_01, REQ_收音机_622_02, REQ_收音机_633_09, REQ_收音机_633_10
// 列表状态机：管理搜索列表/收藏列表的显示切换
Statechart 收音机列表状态机 {
    
  // ===== Start 节点（必需）=====
  Start 系统启动 ;
    
  // ===== 状态定义 =====
  // [REQ_收音机_633_08, REQ_收音机_633_10] 搜索列表选中状态（列表容量可容纳所有搜索到的电台）
  State 搜索列表选中 {
    during_actions: [
      {pre_think: 0 post_think: 0 express: "当前列表 = 搜索列表" type: "action"}
    ]
  };
    
  // [REQ_收音机_6331_01] 收藏列表选中状态
  // [REQ_收音机_6331_02] 收藏列表电台点击播放
  State 收藏列表选中 {
    during_actions: [
      {pre_think: 0 post_think: 0 express: "当前列表 = 收藏列表" type: "action"}
    ]
  };
    
  // ===== 转换定义 =====
  Transition 启动进入搜索列表 {
    condition: "系统启动"
    from: 系统启动
    to: 搜索列表选中
  };
    
  // [REQ_收音机_633_08] 切换到收藏列表
  Transition 切换到收藏列表 {
    condition: "用户选择收藏列表"
    from: 搜索列表选中
    to: 收藏列表选中
  };
    
  // [REQ_收音机_633_08] 切换回搜索列表
  Transition 切换回搜索列表 {
    condition: "用户选择搜索列表"
    from: 收藏列表选中
    to: 搜索列表选中
  };
    
  // [REQ_收音机_621_02] 波段切换时列表跟随切换
  Transition 波段切换更新列表 {
    condition: "波段切换"
    from: 搜索列表选中
    to: 搜索列表选中
  };
}

6收音机/Statecharts/收音机搜索状态机.dsl.dsl_text:
// requirement_ids: REQ_收音机_631_01, REQ_收音机_631_02, REQ_收音机_631_03, REQ_收音机_633_02, REQ_收音机_633_03, REQ_收音机_633_04, REQ_收音机_633_05, REQ_收音机_633_06, REQ_收音机_633_07
// 搜索状态机：管理手动搜索和自动搜索的状态
Statechart 收音机搜索状态机 {
    
  // ===== Start 节点（必需）=====
  Start 系统启动 ;
    
  // ===== 状态定义 =====
  // 空闲状态：未进行搜索
  State 空闲状态 {
    during_actions: [
      {pre_think: 0 post_think: 0 express: "搜索状态 = 空闲" type: "action"}
    ]
  };
    
  // [REQ_收音机_631_01, REQ_收音机_631_02] 手动搜索中：向前/向后搜索有效电台
  State 手动搜索中 {
    during_actions: [
      {pre_think: 0 post_think: 0 express: "搜索状态 = 手动搜索中" type: "action"},
      {pre_think: 0 post_think: 0 express: "系统 = 静音" type: "action"}
    ]
  };
    
  // [REQ_收音机_633_02] FM/AM各自在对应波段内搜索
  // [REQ_收音机_633_03, REQ_收音机_633_04] 自动搜索中：全波段搜索
  State 自动搜索中 {
    during_actions: [
      {pre_think: 0 post_think: 0 express: "搜索状态 = 自动搜索中" type: "action"},
      {pre_think: 0 post_think: 0 express: "系统 = 静音" type: "action"}
    ]
  };
    
  // 搜索找到电台
  State 搜索到电台 {
    during_actions: [
      {pre_think: 0 post_think: 0 express: "搜索状态 = 已找到电台" type: "action"}
    ]
  };
    
  // [REQ_收音机_633_07] 全频段未找到电台
  State 未找到电台 {
    during_actions: [
      {pre_think: 0 post_think: 0 express: "搜索状态 = 未找到" type: "action"},
      {pre_think: 0 post_think: 0 express: "搜索列表 = 不更新" type: "action"},
      {pre_think: 0 post_think: 0 express: "回到搜索前频率" type: "action"}
    ]
  };
    
  // ===== 转换定义 =====
  Transition 启动进入空闲 {
    condition: "系统启动"
    from: 系统启动
    to: 空闲状态
  };
    
  // [REQ_收音机_631_01] 用户点击向前/向后搜索
  Transition 开始手动搜索 {
    condition: "用户点击向前或向后搜索按钮"
    from: 空闲状态
    to: 手动搜索中
  };
    
  // [REQ_收音机_631_01] 搜索到满足信号强度的电台
  Transition 手动搜索找到电台 {
    condition: "搜索到满足规定信号强度的电台"
    from: 手动搜索中
    to: 搜索到电台
  };
    
  // [REQ_收音机_631_03] 无信号区域搜索完全部频段
  Transition 手动搜索未找到 {
    condition: "无信号区域 AND 搜索完全部频段"
    from: 手动搜索中
    to: 未找到电台
  };
    
  // [REQ_收音机_631_03] 搜索过程中点击按钮终止
  Transition 手动搜索终止 {
    condition: "用户再次点击搜索按钮"
    from: 手动搜索中
    to: 空闲状态
  };
    
  // [REQ_收音机_633_03] 用户发起自动搜索
  Transition 开始自动搜索 {
    condition: "用户发起自动搜台"
    from: 空闲状态
    to: 自动搜索中
  };
    
  // [REQ_收音机_633_04] 自动搜索中继续搜索
  Transition 自动搜索继续 {
    condition: "搜索到满足信号强度的电台 AND 未完成全波段搜索"
    from: 自动搜索中
    to: 自动搜索中
  };
    
  // [REQ_收音机_633_05] 全波段搜索结束
  Transition 自动搜索完成 {
    condition: "全波段搜索结束 AND 搜索到电台"
    from: 自动搜索中
    to: 搜索到电台
  };
    
  // [REQ_收音机_633_07] 全频段搜索不到电台
  Transition 自动搜索未找到 {
    condition: "全频段搜索不到满足信号强度的电台"
    from: 自动搜索中
    to: 未找到电台
  };
    
  // [REQ_收音机_633_06] 自动搜索中点击屏幕中止
  Transition 自动搜索中止 {
    condition: "用户点击屏幕"
    from: 自动搜索中
    to: 空闲状态
  };
    
  // 搜索到电台后回到空闲
  Transition 回到空闲 {
    condition: "搜索完成"
    from: 搜索到电台
    to: 空闲状态
  };
    
  // 未找到电台后回到空闲
  Transition 未找到回到空闲 {
    condition: "搜索完成"
    from: 未找到电台
    to: 空闲状态
  };
}

6收音机/Statecharts/收音机播放状态机.dsl.dsl_text:
// requirement_ids: REQ_收音机_632_01, REQ_收音机_632_02, REQ_收音机_632_03, REQ_收音机_632_04, REQ_收音机_632_05, REQ_收音机_632_06
// 播放状态机：管理播放/停止/静音状态的切换
Statechart 收音机播放状态机 {
    
  // ===== Start 节点（必需）=====
  Start 系统启动 ;
    
  // ===== 状态定义 =====
  // [REQ_收音机_632_01, REQ_收音机_632_05] 播放状态：输出电台音频并显示频点
  State 播放状态 {
    during_actions: [
      {pre_think: 0 post_think: 0 express: "播放状态 = 播放中" type: "action"},
      {pre_think: 0 post_think: 0 express: "显示电台频点" type: "action"}
    ]
  };
    
  // [REQ_收音机_632_01, REQ_收音机_632_02] 停止状态：收音机静音
  State 停止状态 {
    during_actions: [
      {pre_think: 0 post_think: 0 express: "播放状态 = 已停止" type: "action"},
      {pre_think: 0 post_think: 0 express: "收音机 = 静音" type: "action"}
    ]
  };
    
  // [REQ_收音机_632_03] 弱信号状态：根据整车tuning降低媒体输出音量
  State 弱信号状态 {
    during_actions: [
      {pre_think: 0 post_think: 0 express: "播放状态 = 弱信号" type: "action"},
      {pre_think: 0 post_think: 0 express: "媒体输出音量 = 降低" type: "action"}
    ]
  };
    
  // ===== 转换定义 =====
  // [REQ_收音机_623_01] 系统启动后进入播放状态（lastmode）
  Transition 启动进入播放 {
    condition: "系统启动 AND 有播放记录"
    from: 系统启动
    to: 播放状态
  };
    
  // 系统启动无播放记录时进入停止状态
  Transition 启动进入停止 {
    condition: "系统启动 AND 无播放记录"
    from: 系统启动
    to: 停止状态
  };
    
  // [REQ_收音机_632_01] 播放状态点击播放/停止按键 → 停止
  Transition 按键停止播放 {
    condition: "用户点击播放_停止按键"
    from: 播放状态
    to: 停止状态
  };
    
  // [REQ_收音机_632_01] 停止状态点击播放/停止按键 → 播放
  Transition 按键开始播放 {
    condition: "用户点击播放_停止按键"
    from: 停止状态
    to: 播放状态
  };
    
  // [REQ_收音机_632_04] 语音命令停止
  Transition 语音停止播放 {
    condition: "语音命令为停止"
    from: 播放状态
    to: 停止状态
  };
    
  // [REQ_收音机_632_04] 语音命令播放
  Transition 语音开始播放 {
    condition: "语音命令为播放"
    from: 停止状态
    to: 播放状态
  };
    
  // [REQ_收音机_632_03] 信号弱时进入弱信号状态
  Transition 信号弱进入弱信号 {
    condition: "当前电台信号强度不满足规定"
    from: 播放状态
    to: 弱信号状态
  };
    
  // 信号恢复时回到播放状态
  Transition 信号恢复回到播放 {
    condition: "信号强度恢复正常"
    from: 弱信号状态
    to: 播放状态
  };
    
  // [REQ_收音机_632_06] 点击列表电台进入播放
  Transition 点击列表电台开始播放 {
    condition: "用户点击搜索列表或收藏列表中的电台"
    from: 停止状态
    to: 播放状态
  };
}

6收音机/Statecharts/收音机波段状态机.dsl.dsl_text:
// requirement_ids: REQ_收音机_621_02, REQ_收音机_623_01
// 波段状态机：管理FM/AM波段的切换
Statechart 收音机波段状态机 {
    
  // ===== Start 节点（必需）=====
  // [REQ_收音机_623_01] 默认FM初始频率
  Start 系统启动 ;
    
  // ===== 状态定义 =====
  // [REQ_收音机_621_01] FM频率范围 87.5MHz-108.0MHz
  // [REQ_收音机_623_01] 无播放记录时默认FM 87.5MHz
  State FM波段 {
    during_actions: [
      {pre_think: 0 post_think: 0 express: "当前波段 = FM" type: "action"},
      {pre_think: 0 post_think: 0 express: "频率范围 = 87.5MHz_108.0MHz" type: "action"},
      {pre_think: 0 post_think: 0 express: "搜索步长 = FM搜索步长" type: "action"}
    ]
  };
    
  // [REQ_收音机_621_01] AM频率范围 531kHz-1602kHz
  // [REQ_收音机_623_01] 无播放记录时AM默认531kHz
  State AM波段 {
    during_actions: [
      {pre_think: 0 post_think: 0 express: "当前波段 = AM" type: "action"},
      {pre_think: 0 post_think: 0 express: "频率范围 = 531kHz_1602kHz" type: "action"},
      {pre_think: 0 post_think: 0 express: "搜索步长 = AM搜索步长" type: "action"}
    ]
  };
    
  // ===== 转换定义 =====
  // [REQ_收音机_623_01] 系统启动默认进入FM波段
  Transition 启动进入FM波段 {
    condition: "系统启动 AND 默认波段为FM"
    from: 系统启动
    to: FM波段
  };
    
  // [REQ_收音机_621_02] 用户从FM切换到AM
  Transition 切换到AM波段 {
    condition: "用户切换波段到AM"
    from: FM波段
    to: AM波段
  };
    
  // [REQ_收音机_621_02] 用户从AM切换到FM
  Transition 切换到FM波段 {
    condition: "用户切换波段到FM"
    from: AM波段
    to: FM波段
  };
}

7蓝牙音乐/DialogMaps/蓝牙音乐页签.dsl.dsl_text:
// requirement_ids: REQ_BT-MUSIC-001_07-03_02, REQ_BT-MUSIC-001_07-03_03, REQ_BT-MUSIC-001_07-03_04, REQ_BT-MUSIC-001_07-03_05, REQ_BT-MUSIC-001_07-03_06
