    widgets: [
      { widget_id: "WDG_001" type: "button" name: "暂停按钮" action: "暂停蓝牙音乐播放" action_type: "set_state" target: null condition: "" },
      { widget_id: "WDG_002" type: "button" name: "继续按钮" action: "继续蓝牙音乐播放" action_type: "set_state" target: null condition: "" },
      { widget_id: "WDG_003" type: "button" name: "下一首按钮" action: "切换到下一首蓝牙音乐" action_type: "execute" target: null condition: "" },
      { widget_id: "WDG_004" type: "button" name: "上一首按钮" action: "切换到上一首蓝牙音乐" action_type: "execute" target: null condition: "" },
      { widget_id: "WDG_005" type: "slider" name: "音量调节控件" action: "调节蓝牙音乐播放音量" action_type: "set_value" target: null condition: "" },
      { widget_id: "WDG_006" type: "label" name: "歌曲名称显示" action: "显示当前播放歌曲名称" action_type: "execute" target: null condition: "" },
      { widget_id: "WDG_007" type: "label" name: "歌手显示" action: "显示当前播放歌手" action_type: "execute" target: null condition: "" },
      { widget_id: "WDG_008" type: "progress" name: "播放进度显示" action: "显示当前播放进度" action_type: "execute" target: null condition: "" }
    ]
  };
    
  // ===== 跳转关系 =====
  Transition 进入蓝牙音乐页签 {
    trigger: "WDG_ENTRY"
    trigger_type: "auto"
    from: 多媒体中心入口
