7蓝牙音乐/Environment.dsl.dsl_text:
// requirement_ids: REQ_BT-MUSIC-001_07-01_01, REQ_BT-MUSIC-001_07-02_01, REQ_BT-MUSIC-001_07-03_01, REQ_BT-MUSIC-001_07-03_02, REQ_BT-MUSIC-001_07-03_03
Environment {
  // === 建模对象（系统本身）===
  // REQ_BT-MUSIC-001_07-01_01: 使用智能座舱系统蓝牙播放音乐
  Machine 蓝牙音乐模块;

  // === 外部设备 ===
  // REQ_BT-MUSIC-001_07-03_01: 手机作为蓝牙音乐音源设备
  Device 手机;
  // REQ_BT-MUSIC-001_07-03_01: 车机音响输出蓝牙音乐音频
  Device 车机音响;
  // REQ_BT-MUSIC-001_07-03_02, REQ_BT-MUSIC-001_07-03_03, REQ_BT-MUSIC-001_07-03_05, REQ_BT-MUSIC-001_07-03_06: 蓝牙音乐功能主界面
  Device 车机_蓝牙音乐页签;

  // === 人类参与者 ===
  Human 驾驶员;

  // === 连接定义 ===

  // REQ_BT-MUSIC-001_07-03_01: 蓝牙连接后，手机音乐通过车机音响播放
  Connect from 手机 to 蓝牙音乐模块 {
    Interaction 蓝牙音频数据流 { Event 手机通过蓝牙A2DP发送音频数据 };
    Interaction 手机播放控制指令 { Event 手机发送播放控制指令 };
  };

  // REQ_BT-MUSIC-001_07-03_01: 车机音响输出蓝牙音乐
  Connect from 蓝牙音乐模块 to 车机音响 {
    Interaction 音频输出 { Event 蓝牙音乐模块输出音频至车机音响 };
  };

  // REQ_BT-MUSIC-001_07-03_02, REQ_BT-MUSIC-001_07-03_03: 蓝牙连接状态影响播放策略
  Connect from 手机 to 蓝牙音乐模块 {
    Interaction 蓝牙连接状态 { Event 蓝牙连接已建立 };
  };

  // REQ_BT-MUSIC-001_07-03_05: 驾驶员通过蓝牙音乐页签进行播放控制
  Connect from 驾驶员 to 车机_蓝牙音乐页签 {
    Interaction 点击暂停按钮 { Event 驾驶员点击暂停按钮 };
    Interaction 点击继续按钮 { Event 驾驶员点击继续按钮 };
    Interaction 点击下一首按钮 { Event 驾驶员点击下一首按钮 };
    Interaction 点击上一首按钮 { Event 驾驶员点击上一首按钮 };
    Interaction 调节音量 { Event 驾驶员在车机侧调节音量 };
  };

  // REQ_BT-MUSIC-001_07-03_05: 蓝牙音乐页签将控制指令发送给模块
  Connect from 车机_蓝牙音乐页签 to 蓝牙音乐模块 {
    Interaction 暂停指令 { Event 蓝牙音乐页签发送暂停指令 };
    Interaction 继续指令 { Event 蓝牙音乐页签发送继续指令 };
    Interaction 下一首指令 { Event 蓝牙音乐页签发送下一首指令 };
    Interaction 上一首指令 { Event 蓝牙音乐页签发送上一首指令 };
    Interaction 音量调节指令 { Event 蓝牙音乐页签发送音量调节指令 };
  };

  // REQ_BT-MUSIC-001_07-03_06: 模块向蓝牙音乐页签发送播放信息用于展示
  Connect from 蓝牙音乐模块 to 车机_蓝牙音乐页签 {
    Interaction 歌曲名称显示 { Event 蓝牙音乐模块更新歌曲名称 };
    Interaction 歌手显示 { Event 蓝牙音乐模块更新歌手信息 };
    Interaction 播放进度显示 { Event 蓝牙音乐模块更新播放进度 };
  };

  // 蓝牙音乐页签向驾驶员展示播放信息
  Connect from 车机_蓝牙音乐页签 to 驾驶员 {
    Interaction 展示播放信息 { Event 蓝牙音乐页签显示歌曲名歌手和播放进度 };
  };

  // REQ_BT-MUSIC-001_07-03_07b: 媒体服务切换事件（驾驶员切换到其他媒体服务）
  Connect from 驾驶员 to 蓝牙音乐模块 {
    Interaction 媒体服务切换 { Event 驾驶员切换至其他媒体服务 };
    Interaction 切换回蓝牙音乐 { Event 驾驶员切换回蓝牙音乐播放服务 };
  };

  // REQ_BT-MUSIC-001_07-03_08b: 临时性声音播放事件
  Connect from 驾驶员 to 蓝牙音乐模块 {
    Interaction 临时声音播放 { Event 发生临时性声音播放 };
    Interaction 临时声音结束 { Event 临时性声音播放结束 };
  };
}

