  Start 系统启动 ;
    
  // ===== 状态定义 =====
  // REQ_BT-MUSIC-001_07-03_03: 蓝牙已连接但车机显示非蓝牙音乐页签，不播放
  State 已连接未播放 {
  };
    
  // REQ_BT-MUSIC-001_07-03_01, REQ_BT-MUSIC-001_07-03_02: 蓝牙音乐正在播放
  State 蓝牙音乐播放中 {
  };
    
  // REQ_BT-MUSIC-001_07-03_05: 用户主动暂停
  State 用户暂停 {
  };
    
  // REQ_BT-MUSIC-001_07-03_07b: 因媒体服务切换暂停
  State 媒体切换暂停 {
  };
    
  // REQ_BT-MUSIC-001_07-03_08b: 临时声音播放时音量降低或静音
  State 音量降低或静音 {
  };
    
  // ===== 转换定义 =====
  // REQ_BT-MUSIC-001_07-03_03: 蓝牙连接但显示非蓝牙音乐页签时不播放
  Transition 蓝牙连接进入未播放状态 {
    condition: "蓝牙连接已建立 AND 车机显示非蓝牙音乐页签"
    from: 系统启动
    to: 已连接未播放
  };
    
  // REQ_BT-MUSIC-001_07-03_02: 蓝牙连接且显示蓝牙音乐页签时触发播放
  Transition 蓝牙连接并显示蓝牙页签进入播放 {
    condition: "蓝牙连接已建立 AND 车机显示蓝牙音乐页签"
    from: 系统启动
    to: 蓝牙音乐播放中
  };
    
  // REQ_BT-MUSIC-001_07-03_02: 从已连接未播放切换到蓝牙音乐页签后触发播放
  Transition 切换到蓝牙音乐页签后开始播放 {
    condition: "车机切换至蓝牙音乐页签"
    from: 已连接未播放
    to: 蓝牙音乐播放中
  };
    
  // REQ_BT-MUSIC-001_07-03_05: 用户点击暂停
  Transition 播放中用户暂停 {
    condition: "用户点击暂停按钮"
    from: 蓝牙音乐播放中
    to: 用户暂停
  };
    
  // REQ_BT-MUSIC-001_07-03_05: 用户点击继续
  Transition 暂停后用户继续 {
    condition: "用户点击继续按钮"
    from: 用户暂停
    to: 蓝牙音乐播放中
  };
    
  // REQ_BT-MUSIC-001_07-03_07b: 用户切换至其他媒体服务时蓝牙音乐暂停
  Transition 播放中切换至其他媒体服务 {
    condition: "用户切换至本地音乐 OR 用户切换至在线音乐 OR 用户切换至收音机 OR 用户切换至视频播放"
    from: 蓝牙音乐播放中
    to: 媒体切换暂停
  };
    
  // REQ_BT-MUSIC-001_07-03_07c: 切换回蓝牙音乐后自动续播
  Transition 切换回蓝牙音乐后自动续播 {
    condition: "用户切换回蓝牙音乐播放服务"
    from: 媒体切换暂停
    to: 蓝牙音乐播放中
  };
    
  // REQ_BT-MUSIC-001_07-03_08b: 临时性声音播放时降低音量或静音
  Transition 播放中发生临时声音 {
    condition: "发生临时性声音播放(电话/语音/导航)"
    from: 蓝牙音乐播放中
    to: 音量降低或静音
  };
    
  // REQ_BT-MUSIC-001_07-03_08b: 临时声音播放结束后恢复
  Transition 临时声音结束后恢复播放 {
    condition: "临时性声音播放结束"
    from: 音量降低或静音
    to: 蓝牙音乐播放中
  };
    
  // 从用户暂停切换到其它媒体服务
  Transition 用户暂停后切换至其他媒体服务 {
    condition: "用户切换至其他媒体服务"
    from: 用户暂停
    to: 媒体切换暂停
  };
}

