8U盘音乐/ExternalScenarios/music_format_val.dsl_text:
// requirement_id: REQ_udisk-music_8.2_04
// 用户选择音乐文件时系统进行格式校验的场景

Scenario 校验音乐文件格式 {
    // [前置条件] U盘已连接；U盘内存在音乐文件；用户已选择某个音乐文件
    // --- 正文开始 ---
    Interaction 用户选择音乐文件;
    Interaction 读取音乐元数据;
    Interaction 校验文件格式;
    if ( 文件格式 in [ MP3, FLAC, WAV ] ) {
        Interaction 文件格式支持播放;
        Interaction 发送播放命令;
        Interaction 播放音乐;
        Interaction 显示播放状态;
    } else {
        Interaction 文件格式不支持播放;
        Interaction 显示不支持格式提示;
    }
    // --- 正文结束 ---
    // [后置条件] 格式为 MP3/FLAC/WAV 的文件正常播放；其他格式文件显示不支持提示
}

