8U盘音乐/ExternalScenarios/udisk_connection.dsl_text:
// requirement_id: REQ_udisk-music_8.2_01, REQ_udisk-music_8.2_02, REQ_udisk-music_8.2_03, REQ_udisk-music_8.2_04
// 用户连接U盘并播放音乐的交互场景（含文件格式校验）

Scenario U盘连接与音乐播放 {
  Interaction 用户插入U盘;
  Interaction U盘数据读取交互;
  Interaction U盘音乐模块识别音乐文件并分类;
  Interaction 显示播放状态;
  if ( 音乐列表为空 == true ) {
    Interaction 显示暂无音乐可播放;
  }
  if ( 音乐列表为空 == false ) {
    Interaction 显示音乐列表按歌曲歌手专辑分类;
  }
  Interaction 用户选择音乐文件;
  Interaction 读取音乐元数据;
  Interaction 校验文件格式;
  if ( 文件格式 in [ MP3, FLAC, WAV ] ) {
    Interaction 文件格式支持播放;
    Interaction 发送播放命令;
    Interaction 播放音乐;
    Interaction 输出音频流;
  } else {
    Interaction 文件格式不支持播放;
    Interaction 显示不支持格式提示;
  }
}

8U盘音乐/Statecharts/playback_state.dsl.dsl_text:
// requirement_id: REQ_udisk-music_8.2_04, REQ_udisk-music_8.2_07, REQ_udisk-music_8.2_08, REQ_udisk-music_8.2_09
// U盘音乐播放状态机（含文件格式校验）

Statechart PlaybackState {
  Start 开始;
  
  State 停止 {
  };
  
  State 文件格式校验中 {
  };
  
  State 格式支持播放 {
  };
  
  State 格式不支持 {
  };
  
  State 播放中 {
  };
  
  State 暂停 {
  };
  
  State 音量降低或静音 {
  };
  
  Transition 转到停止 {
    from: 开始
    to: 停止
  };
  
  Transition 开始文件格式校验 {
    from: 停止
    to: 文件格式校验中
  };
  
  Transition 格式校验通过 {
    from: 文件格式校验中
    to: 格式支持播放
  };
  
  Transition 格式校验不通过 {
    from: 文件格式校验中
    to: 格式不支持
  };
  
  Transition 格式支持后开始播放 {
    from: 格式支持播放
    to: 播放中
  };
  
  Transition 格式不支持后回到停止 {
    from: 格式不支持
    to: 停止
  };
  
  Transition 转到暂停 {
    from: 播放中
    to: 暂停
  };
  
  Transition 转到音量降低或静音 {
    from: 播放中
    to: 音量降低或静音
  };
  
  Transition 恢复播放 {
    from: 暂停
    to: 播放中
  };
  
  Transition 音量恢复播放 {
    from: 音量降低或静音
    to: 播放中
  };
  
  Transition 停止播放 {
    from: 暂停
    to: 停止
  };
  
  Transition 静音停止播放 {
    from: 音量降低或静音
    to: 停止
  };
}

8U盘音乐/Statecharts/udisk_connection_state.dsl_text:
// requirement_id: REQ_udisk-music_8.2_01, REQ_udisk-music_8.2_02
// U盘连接状态机

Statechart UdiskConnectionState {
  Start 开始;
  
  State 未连接 {
  };
  
  State 扫描中 {
  };
  
  State 已连接 {
  };
  
  State 扫描失败 {
  };
  
  Transition 转到未连接 {
    from: 开始
    to: 未连接
  };
  
  Transition 转到扫描中 {
    from: 未连接
    to: 扫描中
  };
  
  Transition 转到已连接 {
    from: 扫描中
    to: 已连接
  };
  
  Transition 转到扫描失败 {
    from: 扫描中
    to: 扫描失败
  };
  
  Transition 回到未连接 {
    from: 已连接
    to: 未连接
  };
  
  Transition 重试扫描 {
    from: 扫描失败
    to: 扫描中
  };
}

